-- 交任务文本重译：按**当前英文**（迁移 20260511154529 之后的版本）重写 OfferRewardText_loc4
-- 由本会话按 238 句唯一英文逐句翻译，410 条（其中 2 条英文为空跳过 → 共 408 条 UPDATE）
SET NAMES utf8mb4;

UPDATE `locales_quest` SET `OfferRewardText_loc4` = '你在部族中的荣誉已无可置疑。你在祖尔格拉布取下无数性命。敌人在你的信念前倒下，敌人在你的力量前倒下。$B$B这是思考者腰带。它是荣誉的象征。它是强大的魔精。现在，它归你了。' WHERE `entry` = 8054 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '你在部族中的荣誉已无可置疑。你在祖尔格拉布取下无数性命。敌人在你的信念前倒下，敌人在你的力量前倒下。$B$B这是思考者腰带。它是荣誉的象征。它是强大的魔精。现在，它归你了。');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '干得不错，$N。挑一副护手吧，聊表谢意。' WHERE `entry` = 9333 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '干得不错，$N。挑一副护手吧，聊表谢意。');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '愿这些物品能在往后的战斗里帮上你的忙。' WHERE `entry` = 9334 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '愿这些物品能在往后的战斗里帮上你的忙。');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '谢谢你，$N。这是你的神圣磨刀石，请谨慎使用。' WHERE `entry` = 9335 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '谢谢你，$N。这是你的神圣磨刀石，请谨慎使用。');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '给你，$N。外面小心些。我们人手不多，可经不起战场上再多伤亡。' WHERE `entry` = 9336 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '给你，$N。外面小心些。我们人手不多，可经不起战场上再多伤亡。');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '给你，$N。外面小心些。我们人手不多，可经不起战场上再多伤亡。' WHERE `entry` = 9337 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '给你，$N。外面小心些。我们人手不多，可经不起战场上再多伤亡。');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '收下这面战袍，骄傲地穿着它。也许你的作为会激励更多人拿起武器，支援我们对抗天灾军团的战斗。' WHERE `entry` = 9343 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '收下这面战袍，骄傲地穿着它。也许你的作为会激励更多人拿起武器，支援我们对抗天灾军团的战斗。');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '啊，友情——对艺术的热爱——对更高存在的虔诚——还有那永世奉献与忠诚的誓言。真是些了不起的范例，你做得太好了！老实说，我几乎把它们全都忘了，请原谅我的失礼。这把弓自有主见，有时连它自己射箭我都察觉不到！谁知道呢，说不定你出门的路上就成了它的下一个目标！$B$B<奎·Q一想到这儿就笑了。>$B$B喏，让我为你的辛劳给点奖赏。收下这箱子，里头是艾泽拉斯最精美的衣物。用它们的魅力去讨好你心里珍视的人吧！' WHERE `entry` = 41274 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '啊，友情——对艺术的热爱——对更高存在的虔诚——还有那永世奉献与忠诚的誓言。真是些了不起的范例，你做得太好了！老实说，我几乎把它们全都忘了，请原谅我的失礼。这把弓自有主见，有时连它自己射箭我都察觉不到！谁知道呢，说不定你出门的路上就成了它的下一个目标！$B$B<奎·Q一想到这儿就笑了。>$B$B喏，让我为你的辛劳给点奖赏。收下这箱子，里头是艾泽拉斯最精美的衣物。用它们的魅力去讨好你心里珍视的人吧！');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '<你猜想自己看到的是这位土灵脸上的笑容。巨人身上取下的粗糙宝石在他宽大的手掌里显得很小。他只点了点头，随后让你再次跪下。$B$B当他的手掌再次按上你时，你眼前的一切清晰了许多，尽管这过程依旧让你疲惫不堪。三颗宝石在你内视中显现。所幸你认得它们：一颗火烬石、一颗星红宝石和一颗黄水晶。接着你看到同样的宝石被切出一种你从未见过的刻面。你凝神细看，记住了每一个动作。这份智慧就此刻入你的心中。>' WHERE `entry` = 41279 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '<你猜想自己看到的是这位土灵脸上的笑容。巨人身上取下的粗糙宝石在他宽大的手掌里显得很小。他只点了点头，随后让你再次跪下。$B$B当他的手掌再次按上你时，你眼前的一切清晰了许多，尽管这过程依旧让你疲惫不堪。三颗宝石在你内视中显现。所幸你认得它们：一颗火烬石、一颗星红宝石和一颗黄水晶。接着你看到同样的宝石被切出一种你从未见过的刻面。你凝神细看，记住了每一个动作。这份智慧就此刻入你的心中。>');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '<这位匠人端详着那枚刻面过的活力宝石。他琥珀色的眼睛仔细审视着这颗闪亮红宝石的每一道切面与棱角。评定完毕后，他把宝石递还给你——随后躬身致意。$B$B你通过了考验！瑟格雷恩把你引到他的工作台前，迫不及待要把自己的知识传授给这位新学生。>' WHERE `entry` = 41282 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '<这位匠人端详着那枚刻面过的活力宝石。他琥珀色的眼睛仔细审视着这颗闪亮红宝石的每一道切面与棱角。评定完毕后，他把宝石递还给你——随后躬身致意。$B$B你通过了考验！瑟格雷恩把你引到他的工作台前，迫不及待要把自己的知识传授给这位新学生。>');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '嗯，嗯，没我想的那么糟。不过，这明显带着姆埃瓦那种粗糙手艺的印记。好在现在你落到我手里了，用不了多久，我就能把你调教成一个能用的珠宝匠！先做这件可爱的小饰品吧，照着做应该不难……但愿如此。' WHERE `entry` = 41283 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '嗯，嗯，没我想的那么糟。不过，这明显带着姆埃瓦那种粗糙手艺的印记。好在现在你落到我手里了，用不了多久，我就能把你调教成一个能用的珠宝匠！先做这件可爱的小饰品吧，照着做应该不难……但愿如此。');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '我不知道你怎么想，但看着这些小宝贝在探矿镜的光下闪闪发亮，我是永远看不腻的。你一定能理解。既然说定了——来，听仔细，我可不说第二遍！' WHERE `entry` = 41284 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '我不知道你怎么想，但看着这些小宝贝在探矿镜的光下闪闪发亮，我是永远看不腻的。你一定能理解。既然说定了——来，听仔细，我可不说第二遍！');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '血迹斑斑、湿漉漉、满是泥浆。唉，看到我一件得意之作被如此糟践，真让我心痛。不管怎么说，谢谢你把它取回来。告诉我，你是在他那被打烂的尸体上找到的，还是被别人的脏手顺走的？算了，别告诉我，我宁愿不知道。$B$B作为你这桩高尚之举的回报，我来教你亲手制作这条项圈。' WHERE `entry` = 41285 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '血迹斑斑、湿漉漉、满是泥浆。唉，看到我一件得意之作被如此糟践，真让我心痛。不管怎么说，谢谢你把它取回来。告诉我，你是在他那被打烂的尸体上找到的，还是被别人的脏手顺走的？算了，别告诉我，我宁愿不知道。$B$B作为你这桩高尚之举的回报，我来教你亲手制作这条项圈。');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '干得漂亮，我在这儿很少能一次拿到这么多珠宝加工材料。我想得向古尔米瑞道声谢，毕竟在等新情报的这段时间，他总算给了我一件实实在在的活儿。$B$B不过说回你。让我教你怎么做出这些精致的小饰品。' WHERE `entry` = 41287 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '干得漂亮，我在这儿很少能一次拿到这么多珠宝加工材料。我想得向古尔米瑞道声谢，毕竟在等新情报的这段时间，他总算给了我一件实实在在的活儿。$B$B不过说回你。让我教你怎么做出这些精致的小饰品。');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '或许很微弱，但这些宝石里确实透出力量。最好的珠宝匠能从中提炼出强大的精髓，并将其增幅到前所未有的地步。若容我说一句：总有一天，你也会走到那一步。' WHERE `entry` = 41288 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '或许很微弱，但这些宝石里确实透出力量。最好的珠宝匠能从中提炼出强大的精髓，并将其增幅到前所未有的地步。若容我说一句：总有一天，你也会走到那一步。');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '令人心惊的消息。你描述的这些，我听着太熟悉了——许多巨魔帝国都毁在自己的狂妄上，自以为高踞于族人或神灵之上。看到你安然归来，我就更放心了。$B$B那么，我们是不是该从这些残破的书页里挖出点线索了？' WHERE `entry` = 41289 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '令人心惊的消息。你描述的这些，我听着太熟悉了——许多巨魔帝国都毁在自己的狂妄上，自以为高踞于族人或神灵之上。看到你安然归来，我就更放心了。$B$B那么，我们是不是该从这些残破的书页里挖出点线索了？');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '了不起，如此深刻的切割与打磨。谁都看得出你为这些作品倾注了多少血汗与泪水。人赋予作品的生命，与技术步骤同样重要。没有灵魂的首饰只是一件商品，是对这门手艺千年传承的亵渎。$B$B而你已证明，你的心跳与艾泽拉斯同频——你与它的精魂共鸣，并把那份能量注入自己的艺术。作为我的新学生，请允许我把神圣的知识传授给你。这是你应得的。$B$B哦，若你以后遇见我从前哪个学生，告诉他们随时可以来看我——我想，隔了这些年，有个人做伴也无妨。' WHERE `entry` = 41292 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '了不起，如此深刻的切割与打磨。谁都看得出你为这些作品倾注了多少血汗与泪水。人赋予作品的生命，与技术步骤同样重要。没有灵魂的首饰只是一件商品，是对这门手艺千年传承的亵渎。$B$B而你已证明，你的心跳与艾泽拉斯同频——你与它的精魂共鸣，并把那份能量注入自己的艺术。作为我的新学生，请允许我把神圣的知识传授给你。这是你应得的。$B$B哦，若你以后遇见我从前哪个学生，告诉他们随时可以来看我——我想，隔了这些年，有个人做伴也无妨。');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '<巧匠端详着你的成品与那件仿制品。>$B$B接近了。没有我的指点，你能把我的学生的步骤复现到这种程度，着实惊人。不过，要衡量你真正的潜力，我要你在我的指导下亲手做出一件作品。来，仔细听好，让我看看你听得够不够认真。' WHERE `entry` = 41293 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '<巧匠端详着你的成品与那件仿制品。>$B$B接近了。没有我的指点，你能把我的学生的步骤复现到这种程度，着实惊人。不过，要衡量你真正的潜力，我要你在我的指导下亲手做出一件作品。来，仔细听好，让我看看你听得够不够认真。');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '以本来面目观照世界，看似简单寻常，但唯有愿意深入其中的人，才能真正洞悉其本质。$B$B你已向我证明你是这样的人。用心听我说的话，它们会给你新的领悟。' WHERE `entry` = 41294 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '以本来面目观照世界，看似简单寻常，但唯有愿意深入其中的人，才能真正洞悉其本质。$B$B你已向我证明你是这样的人。用心听我说的话，它们会给你新的领悟。');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '<看到你带来的物件，巧匠出奇地郑重。他轻声一笑，才重新看向你。>$B$B谢谢你。我很高兴你来找我。来，我把加莉特蕾娅在我门下时设计的一件东西送给你。' WHERE `entry` = 41295 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '<看到你带来的物件，巧匠出奇地郑重。他轻声一笑，才重新看向你。>$B$B谢谢你。我很高兴你来找我。来，我把加莉特蕾娅在我门下时设计的一件东西送给你。');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '听来悲惨又骇人——无论是来自我们母星的德莱尼人的干预，还是库米沙一心想要回到故土的执念。我带着族人来到此地，是为了寻找一处避风港，一处终有一天能再度称之为家的庇护所。有了这卷轴上的智慧与德莱尼水晶的魔法，我们或许能实现它——一起。$B$B请放心，你为我族人所做的一切不会被遗忘。既然你读不懂这经卷，就让我为你讲讲其中的奥义吧。' WHERE `entry` = 41299 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '听来悲惨又骇人——无论是来自我们母星的德莱尼人的干预，还是库米沙一心想要回到故土的执念。我带着族人来到此地，是为了寻找一处避风港，一处终有一天能再度称之为家的庇护所。有了这卷轴上的智慧与德莱尼水晶的魔法，我们或许能实现它——一起。$B$B请放心，你为我族人所做的一切不会被遗忘。既然你读不懂这经卷，就让我为你讲讲其中的奥义吧。');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '<塔瓦斯德打开袋子，一脸恼火。>$B$B什么？！这才是我被答应的一半！哦，这个该死的刽子手、卑鄙的滑头，连他那帮凶神恶煞的保镖也一起见鬼去吧！不过，至少我还活着，对吧？这得谢谢你——说真的，我很感激！你毫不犹豫地为我冒险，如今这种事可不多见。但愿这帮恶棍不会再来找我麻烦。$B$B不过请告诉我：你替我送去的那件首饰，你莫非是珠宝匠？若是，请允许我把一份专利设计分享给你，作为你这份英勇的酬谢！' WHERE `entry` = 41302 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '<塔瓦斯德打开袋子，一脸恼火。>$B$B什么？！这才是我被答应的一半！哦，这个该死的刽子手、卑鄙的滑头，连他那帮凶神恶煞的保镖也一起见鬼去吧！不过，至少我还活着，对吧？这得谢谢你——说真的，我很感激！你毫不犹豫地为我冒险，如今这种事可不多见。但愿这帮恶棍不会再来找我麻烦。$B$B不过请告诉我：你替我送去的那件首饰，你莫非是珠宝匠？若是，请允许我把一份专利设计分享给你，作为你这份英勇的酬谢！');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '哦，哇！这东西几乎跟我的鼻子一样大！那些冒险者果然没吹牛。还有你带来的项链，做工精细得惊人，真了不起。我说过吧，你在珠宝加工上有天分。真的，你帮了我大忙。藏宝海湾那些自以为了不起的家伙，看到这宝贝准会流口水，你等着瞧！为答谢你这一路的辛苦与帮助，我把一份我个人最中意的设计分享给你。' WHERE `entry` = 41305 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '哦，哇！这东西几乎跟我的鼻子一样大！那些冒险者果然没吹牛。还有你带来的项链，做工精细得惊人，真了不起。我说过吧，你在珠宝加工上有天分。真的，你帮了我大忙。藏宝海湾那些自以为了不起的家伙，看到这宝贝准会流口水，你等着瞧！为答谢你这一路的辛苦与帮助，我把一份我个人最中意的设计分享给你。');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '嚯，这才是好东西。我一眼就看出，用这神奇的混合物能把特拉希斯那摊烂摊子救回来。你是跟萨拉辛一起来的？他是个独来独往的……男人？还是蛇？我不清楚，不过到目前为止，他倒没拒绝过跟我长谈珠宝加工的历史与艺术。谁知道呢，说不定哪天我会跟你讲讲我俩是怎么认识的！$B$B既然你帮我避免了一场尴尬的顾客冲突，那就让我给你点回报。我猜你珠宝加工也不差，对吧？别惊讶，我毕竟是这行的大师。就让我免费分享些心得，权当报酬。' WHERE `entry` = 41309 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '嚯，这才是好东西。我一眼就看出，用这神奇的混合物能把特拉希斯那摊烂摊子救回来。你是跟萨拉辛一起来的？他是个独来独往的……男人？还是蛇？我不清楚，不过到目前为止，他倒没拒绝过跟我长谈珠宝加工的历史与艺术。谁知道呢，说不定哪天我会跟你讲讲我俩是怎么认识的！$B$B既然你帮我避免了一场尴尬的顾客冲突，那就让我给你点回报。我猜你珠宝加工也不差，对吧？别惊讶，我毕竟是这行的大师。就让我免费分享些心得，权当报酬。');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '宝石被劈开了？有意思，不过以那座塔的状况倒也不意外。可把它那样藏起来——麦迪文到底在想什么？还有这个聚焦器……足以证明龙族对掌管魔法一事确有其永恒的职责。我不觉得活着的凡人能造出这种增幅能量流动的装置。$B$B说来苦乐参半，你懂吗？我早已宣誓放弃术士的身份，却无法否认：这第二次帮你，让我心中一种久违的感觉重新亮了起来。看着你完成这件事，我对你能让塔中恐怖安息这件事更有信心了。带上这枚修复好的杖头，再去塔里搜寻剩下的部分。毫无疑问，这会在你探索卡拉赞时起到关键作用。' WHERE `entry` = 41312 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '宝石被劈开了？有意思，不过以那座塔的状况倒也不意外。可把它那样藏起来——麦迪文到底在想什么？还有这个聚焦器……足以证明龙族对掌管魔法一事确有其永恒的职责。我不觉得活着的凡人能造出这种增幅能量流动的装置。$B$B说来苦乐参半，你懂吗？我早已宣誓放弃术士的身份，却无法否认：这第二次帮你，让我心中一种久违的感觉重新亮了起来。看着你完成这件事，我对你能让塔中恐怖安息这件事更有信心了。带上这枚修复好的杖头，再去塔里搜寻剩下的部分。毫无疑问，这会在你探索卡拉赞时起到关键作用。');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '简直出色极了。我们所见印证了我的猜想：魔网水晶是一种能量导管，一旦暴露在高度浓缩的魔法下，便会显现为奥术魔物。你若细看，两块水晶残骸完全相同——这意味着血精灵从蓝龙军团那里取得水晶后，改造了自己的那一块；究竟是用强夺还是合作，我也说不准。$B$B多亏你，我对这片土地及其居民的了解又深了一层。不过，得知蓝龙军团正在做这种可疑的事，仍令人不安。他们很少在意凡人的事务，却会毫不犹豫地阻止对艾泽拉斯魔法的滥用。眼下我们只能观察，并期盼最好的结果。$B$B至于你的奖励：你也是个能干的珠宝匠，对吧？那就让我教你怎么做出一把能增幅持有者魔法能力的法杖。' WHERE `entry` = 41315 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '简直出色极了。我们所见印证了我的猜想：魔网水晶是一种能量导管，一旦暴露在高度浓缩的魔法下，便会显现为奥术魔物。你若细看，两块水晶残骸完全相同——这意味着血精灵从蓝龙军团那里取得水晶后，改造了自己的那一块；究竟是用强夺还是合作，我也说不准。$B$B多亏你，我对这片土地及其居民的了解又深了一层。不过，得知蓝龙军团正在做这种可疑的事，仍令人不安。他们很少在意凡人的事务，却会毫不犹豫地阻止对艾泽拉斯魔法的滥用。眼下我们只能观察，并期盼最好的结果。$B$B至于你的奖励：你也是个能干的珠宝匠，对吧？那就让我教你怎么做出一把能增幅持有者魔法能力的法杖。');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '东西都拿到了？太好了，那我们来验证一下这个猜想如何？$B$B<凡兹翻开书页，把它高高举过头顶。当它靠近空白页时，那些核心与精华开始液化，转移到羊皮纸上——最终凝结成文字，补全了这件首饰的制作说明。>$B$B哇！这真是绝了！我之前说的那些关于这本书的话收回，不得不承认，这玩意真带劲。太不可思议了，过来，我们一起把这一页研究透——没有你的投入，我们走不到这一步！' WHERE `entry` = 41318 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '东西都拿到了？太好了，那我们来验证一下这个猜想如何？$B$B<凡兹翻开书页，把它高高举过头顶。当它靠近空白页时，那些核心与精华开始液化，转移到羊皮纸上——最终凝结成文字，补全了这件首饰的制作说明。>$B$B哇！这真是绝了！我之前说的那些关于这本书的话收回，不得不承认，这玩意真带劲。太不可思议了，过来，我们一起把这一页研究透——没有你的投入，我们走不到这一步！');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '干得漂亮。光是弄到一颗这样的宝石已算了得，我简直无法想象你为拿到三颗费了多少功夫！好，都交给我吧，我正想创作一件杰作！$B$B<凡兹夺过材料，小手飞快地动起来。几分钟后，她把那枚精巧的镜片举到阳光下，正对着空白页。令人意外的是，聚焦的光束非但没有烧焦纸面，反而在原本空白的纸上浮现出繁复的文字。>$B$B我找到了！大获成功！是时候收获我们的成果了！过来，我们一起读读看！' WHERE `entry` = 41319 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '干得漂亮。光是弄到一颗这样的宝石已算了得，我简直无法想象你为拿到三颗费了多少功夫！好，都交给我吧，我正想创作一件杰作！$B$B<凡兹夺过材料，小手飞快地动起来。几分钟后，她把那枚精巧的镜片举到阳光下，正对着空白页。令人意外的是，聚焦的光束非但没有烧焦纸面，反而在原本空白的纸上浮现出繁复的文字。>$B$B我找到了！大获成功！是时候收获我们的成果了！过来，我们一起读读看！');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '我悲痛欲绝。即便在最荒诞的梦里，我也想不到会如此。桑夫·塔斯达尔，曾是我们的酋长、我的导师，也是我族高贵的领袖，竟屈从于燃烧军团的甜言蜜语。若不是你和阿克资阿多，我和族人便会随他回到德拉诺，余生都做军团阴谋的傀儡。$B$B避难所永远欠你一份人情。言语无法表达我对你这份无私的感激有多沉重。所以，请收下这份心意——它来自这座小小圣所里所有德莱尼人。' WHERE `entry` = 41326 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '我悲痛欲绝。即便在最荒诞的梦里，我也想不到会如此。桑夫·塔斯达尔，曾是我们的酋长、我的导师，也是我族高贵的领袖，竟屈从于燃烧军团的甜言蜜语。若不是你和阿克资阿多，我和族人便会随他回到德拉诺，余生都做军团阴谋的傀儡。$B$B避难所永远欠你一份人情。言语无法表达我对你这份无私的感激有多沉重。所以，请收下这份心意——它来自这座小小圣所里所有德莱尼人。');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '$N，我由衷感谢你为避难所做的一切。卡斯塔尔及时联系上了我。再晚一步，后果不堪设想。那么，说说我想跟你说的事……$B$B<阿克资阿多向你呈上一颗浑圆无瑕、泛着青绿光泽的水晶，是你从未见过的东西。>$B$B你眼前这颗是纯净的德莱尼水晶宝石，是我族在德拉诺时最珍视的稀有之物之一。它的地位近乎传说，当然并非童话里那种。虽然只是推测，但我猜这一颗诞生于塔斯达尔的裂隙魔法与我的相撞之时。我想把它给你，作为答谢——也作为一个承诺。只要你有需要，避难所的德莱尼人都会相助，因为没有你，我们早已不复存在。恩基尔·托拉拉尔，朋友，愿扭曲虚空的风眷顾你。' WHERE `entry` = 41327 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '$N，我由衷感谢你为避难所做的一切。卡斯塔尔及时联系上了我。再晚一步，后果不堪设想。那么，说说我想跟你说的事……$B$B<阿克资阿多向你呈上一颗浑圆无瑕、泛着青绿光泽的水晶，是你从未见过的东西。>$B$B你眼前这颗是纯净的德莱尼水晶宝石，是我族在德拉诺时最珍视的稀有之物之一。它的地位近乎传说，当然并非童话里那种。虽然只是推测，但我猜这一颗诞生于塔斯达尔的裂隙魔法与我的相撞之时。我想把它给你，作为答谢——也作为一个承诺。只要你有需要，避难所的德莱尼人都会相助，因为没有你，我们早已不复存在。恩基尔·托拉拉尔，朋友，愿扭曲虚空的风眷顾你。');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '过程很累人，但总算成了：又一颗纯净的宝石。请好好保管它。' WHERE `entry` = 41328 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '过程很累人，但总算成了：又一颗纯净的宝石。请好好保管它。');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '当年在埃达拉斯，我们奉艾萨拉女王之命，在奥术圣殿里研究过无数如今早已被遗忘的符文。其中许多我已随时间淡忘，还有一些则因羞愧而不愿想起。不过看来，那段旧日学识让我们获得了新的智慧——这份智慧你可以自行斟酌使用。来，仔细听好。该上新课了，学生。' WHERE `entry` = 41336 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '当年在埃达拉斯，我们奉艾萨拉女王之命，在奥术圣殿里研究过无数如今早已被遗忘的符文。其中许多我已随时间淡忘，还有一些则因羞愧而不愿想起。不过看来，那段旧日学识让我们获得了新的智慧——这份智慧你可以自行斟酌使用。来，仔细听好。该上新课了，学生。');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '结束了。听闻你那些英勇事迹，压在我心头的恐惧正在消散。我会用窥视翡翠梦境的能力，把这块碎片送回我祖父身边。光是握着它，我就又能感到他那光辉而强大的气息。$B$B他要完全恢复力量还需要相当长的时间，不过伊瑟拉和他的荒野之神同伴们都在他身旁，守护着这位亲爱的朋友与导师。$B$B你对白鹿及其传承的忠诚值得称道。为褒奖你这无私的英雄之举，就让我把变化为玛洛恩雄鹿形态的诀窍传授给你。' WHERE `entry` = 41342 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '结束了。听闻你那些英勇事迹，压在我心头的恐惧正在消散。我会用窥视翡翠梦境的能力，把这块碎片送回我祖父身边。光是握着它，我就又能感到他那光辉而强大的气息。$B$B他要完全恢复力量还需要相当长的时间，不过伊瑟拉和他的荒野之神同伴们都在他身旁，守护着这位亲爱的朋友与导师。$B$B你对白鹿及其传承的忠诚值得称道。为褒奖你这无私的英雄之举，就让我把变化为玛洛恩雄鹿形态的诀窍传授给你。');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '大蜡烛给大胡须！我在这鬼地方的活儿干完了。大胡须把这个送给你，当作谢礼。很好玩的书，你看！' WHERE `entry` = 41344 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '大蜡烛给大胡须！我在这鬼地方的活儿干完了。大胡须把这个送给你，当作谢礼。很好玩的书，你看！');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '箱子打开，一股潮湿的气味涌了出来。里面是一些锈迹斑斑的小玩意——还有一件碎裂之物，竟出奇地完好。你把它拿起来，感到一股危险的气息自其中透出。令人心惊。' WHERE `entry` = 41346 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '箱子打开，一股潮湿的气味涌了出来。里面是一些锈迹斑斑的小玩意——还有一件碎裂之物，竟出奇地完好。你把它拿起来，感到一股危险的气息自其中透出。令人心惊。');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '<蒂莉亚为你完成的任务震惊得说不出话。她端详着失而复得的珍宝，慢慢镇定下来，开口道。>$B$B太不可思议了，简直令人惊叹！你是个了不起的侦探，这么快就查清了这桩十年前的悬案。若我还在自己的庄园，我会让我的兄弟为你授勋、纳入我们的随从。可惜啊，我想这世界的精彩才是你的召唤，而我这不死的躯体却把我困在此地。不过别担心——项链回到我手里，我便能带着轻蔑忍受这无尽的囚笼。$B$B如约，这份东西归你：一枚珍贵红宝石戒指，出自这座塔的主人、守护者麦迪文之手。' WHERE `entry` = 41351 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '<蒂莉亚为你完成的任务震惊得说不出话。她端详着失而复得的珍宝，慢慢镇定下来，开口道。>$B$B太不可思议了，简直令人惊叹！你是个了不起的侦探，这么快就查清了这桩十年前的悬案。若我还在自己的庄园，我会让我的兄弟为你授勋、纳入我们的随从。可惜啊，我想这世界的精彩才是你的召唤，而我这不死的躯体却把我困在此地。不过别担心——项链回到我手里，我便能带着轻蔑忍受这无尽的囚笼。$B$B如约，这份东西归你：一枚珍贵红宝石戒指，出自这座塔的主人、守护者麦迪文之手。');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '我一直害怕有一天要与自己称作朋友的人为敌。唉。$B$B凯斯利尔和许多上层精灵聚居地一样，曾充盈着魔法——那些魔法已随岁月湮没，而我是这片土地上尚未逃离的最后一位幸存者。自从湖水吞没我的家，这些龙族器物就一直在我手里。挑一件吧，它归你了。留个念想，记得我。后会有期。' WHERE `entry` = 41360 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '我一直害怕有一天要与自己称作朋友的人为敌。唉。$B$B凯斯利尔和许多上层精灵聚居地一样，曾充盈着魔法——那些魔法已随岁月湮没，而我是这片土地上尚未逃离的最后一位幸存者。自从湖水吞没我的家，这些龙族器物就一直在我手里。挑一件吧，它归你了。留个念想，记得我。后会有期。');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '我很感激你的付出，$N。这绝不是轻松的差事，你却这么快就给我弄来了这么高品质的材料。$B$B像山脉之血这样的宝石，需要极高的精准与耐心。只要多施加一丝不该有的力道，整颗宝石就会裂成两半。仔细看着，我只有一次机会教你。做完之后这颗宝石就归你——就当是谢你给我带来这么一件稀奇的样品。' WHERE `entry` = 41362 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '我很感激你的付出，$N。这绝不是轻松的差事，你却这么快就给我弄来了这么高品质的材料。$B$B像山脉之血这样的宝石，需要极高的精准与耐心。只要多施加一丝不该有的力道，整颗宝石就会裂成两半。仔细看着，我只有一次机会教你。做完之后这颗宝石就归你——就当是谢你给我带来这么一件稀奇的样品。');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '有意思。这些样本散发的魔法我并不陌生，乍看之下，我甚至要说它们透着德鲁伊的法术。当然，我不该急着下结论。还需要在塞纳里奥议会做进一步研究——他们那些可敬的德鲁伊想必能弄清它们狂暴生长的根源。$B$B$N，我很感激你。请收下一件，作为你辛苦的补偿。' WHERE `entry` = 41363 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '有意思。这些样本散发的魔法我并不陌生，乍看之下，我甚至要说它们透着德鲁伊的法术。当然，我不该急着下结论。还需要在塞纳里奥议会做进一步研究——他们那些可敬的德鲁伊想必能弄清它们狂暴生长的根源。$B$B$N，我很感激你。请收下一件，作为你辛苦的补偿。');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '愿他的灵魂能在圣光中重归安宁。' WHERE `entry` = 41366 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '愿他的灵魂能在圣光中重归安宁。');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '噩梦的黑暗曾笼罩我的思绪，把我一向压住的情绪都逼了出来。某种程度上，我也后悔事情走到这一步。$B$B<纳尔帕克把赞妲拉的头颅放在地上。>$B$B活干得好，就该有好报。谢谢你，$N。' WHERE `entry` = 41367 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '噩梦的黑暗曾笼罩我的思绪，把我一向压住的情绪都逼了出来。某种程度上，我也后悔事情走到这一步。$B$B<纳尔帕克把赞妲拉的头颅放在地上。>$B$B活干得好，就该有好报。谢谢你，$N。');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '这些笔记很珍贵，非常珍贵。我不觉得这时候就能让血色十字军造不出光铸护甲，但至少它回到了我手里。' WHERE `entry` = 41368 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '这些笔记很珍贵，非常珍贵。我不觉得这时候就能让血色十字军造不出光铸护甲，但至少它回到了我手里。');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '太骇人了。即便只是某个狂暴元素残留的遗物，它散发出的压迫感依然令人窒息。有了这份能量源泉，我就能把法杖与束具合而为一，重现麦迪文之杖。不过它虽已复原，却仍不完整——杖头丢失了。至于去哪里找，我就无从知晓了。若它落到你手里，再来找我，我会尽力再帮你一次。' WHERE `entry` = 41369 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '太骇人了。即便只是某个狂暴元素残留的遗物，它散发出的压迫感依然令人窒息。有了这份能量源泉，我就能把法杖与束具合而为一，重现麦迪文之杖。不过它虽已复原，却仍不完整——杖头丢失了。至于去哪里找，我就无从知晓了。若它落到你手里，再来找我，我会尽力再帮你一次。');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '我把麦迪文之杖托付给你——它是魔网魔法的导管，也是异界原初能量的容器。凭它，你可以号令卡拉赞本身狂暴的魔法洪流。别因此自满；你固然强大，但真正能驾驭这法杖的，唯有它从前的主人。尽管如此，这座被诅咒之塔最深处的秘密如今已伏在你脚下，只等着那位意志足够坚定、敢于闯过险途之人前来揭开。$B$B去吧，去取回你如此英勇奋战所追寻的真相！让征服卡拉赞成为你英雄传奇中的一座里程碑！' WHERE `entry` = 41372 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '我把麦迪文之杖托付给你——它是魔网魔法的导管，也是异界原初能量的容器。凭它，你可以号令卡拉赞本身狂暴的魔法洪流。别因此自满；你固然强大，但真正能驾驭这法杖的，唯有它从前的主人。尽管如此，这座被诅咒之塔最深处的秘密如今已伏在你脚下，只等着那位意志足够坚定、敢于闯过险途之人前来揭开。$B$B去吧，去取回你如此英勇奋战所追寻的真相！让征服卡拉赞成为你英雄传奇中的一座里程碑！');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '一张皱巴巴的纸。不管怎么说，看到它变成这样都让人难过。我替你把它复原——把它拿在手里，让我想起了它原来的样子。' WHERE `entry` = 41374 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '一张皱巴巴的纸。不管怎么说，看到它变成这样都让人难过。我替你把它复原——把它拿在手里，让我想起了它原来的样子。');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '好了，符文既已补全，现在就能用了。至于你愿不愿意用，那就随你。' WHERE `entry` = 41376 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '好了，符文既已补全，现在就能用了。至于你愿不愿意用，那就随你。');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '大师是个难以捉摸的人，我大概永远也弄不懂他的心思。好在我们要的不是这个，对吧？$B$B你带来的这颗珍珠，真是不同寻常。大师的每个学生都会从他——严格说也包括我——那里得到一件私人礼物，作为成就的凭证。我的是我在千针石林杀掉的一只蝎子的尾刺。至于你……你觉得一枚坠饰如何？' WHERE `entry` = 41389 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '大师是个难以捉摸的人，我大概永远也弄不懂他的心思。好在我们要的不是这个，对吧？$B$B你带来的这颗珍珠，真是不同寻常。大师的每个学生都会从他——严格说也包括我——那里得到一件私人礼物，作为成就的凭证。我的是我在千针石林杀掉的一只蝎子的尾刺。至于你……你觉得一枚坠饰如何？');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '以科赞的矿脉起誓！这味道太呛人了。随便谁闻上一口，壮实的船员也得当场倒地。$N，干得漂亮。虽然我们保住了这一头的作业，但还得查清他们到底从哪儿弄来这些补给——我敢肯定，风险投资公司不过是个中间人。总之，到目前为止你做得很好，我为你备了份奖励。别招惹麻烦，冒险者，我可不想看到你送命。' WHERE `entry` = 41392 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '以科赞的矿脉起誓！这味道太呛人了。随便谁闻上一口，壮实的船员也得当场倒地。$N，干得漂亮。虽然我们保住了这一头的作业，但还得查清他们到底从哪儿弄来这些补给——我敢肯定，风险投资公司不过是个中间人。总之，到目前为止你做得很好，我为你备了份奖励。别招惹麻烦，冒险者，我可不想看到你送命。');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '这些就够了。有了这些效力强劲的蘑菇，我能为你调制一剂格外强力的梦境帷幕。没有它，我怕你会过早被拉入梦境，再也回不来。现在打起精神，$N。要获得梦境之视，你得去觐见艾泽拉斯最古老的绿龙之一。' WHERE `entry` = 41396 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '这些就够了。有了这些效力强劲的蘑菇，我能为你调制一剂格外强力的梦境帷幕。没有它，我怕你会过早被拉入梦境，再也回不来。现在打起精神，$N。要获得梦境之视，你得去觐见艾泽拉斯最古老的绿龙之一。');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '我明白了。尽管听着令人沉重，维瑟库斯的轻蔑也可以理解。像他这样的古老存在，在目睹凡人千万年来的种种劣行之后，善意很容易动摇。我仍希望他能继续看到你们这些族人所蕴藏的潜力。$B$B不过，知道他可以沟通、也没有沦为噩梦的牺牲品，总算让我心里一块石头落了地。' WHERE `entry` = 41397 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '我明白了。尽管听着令人沉重，维瑟库斯的轻蔑也可以理解。像他这样的古老存在，在目睹凡人千万年来的种种劣行之后，善意很容易动摇。我仍希望他能继续看到你们这些族人所蕴藏的潜力。$B$B不过，知道他可以沟通、也没有沦为噩梦的牺牲品，总算让我心里一块石头落了地。');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '<宁静降临暮光林地。梦魇再一次被击退，但能维持多久，无人知晓。你心里明白，翡翠梦境之战尚未结束，然而想到那些坚定的守卫会继续这场正义之战，你便感到一丝慰藉。$B$B在你面前矗立着堪称自然最强之力的存在。青绿色的毛皮如星空般闪耀，他的双眼映出一片深蓝的智慧之海。你以为他力量的重压会把你压垮，可迎面而来的却是那熟悉的暖意——如清晨的阳光微风拂过挂满露珠的青草。$B$B你抬眼上望，视线与这位半神相接，一股力量之感奔涌全身。那是无可比拟的感受：成长、欣赏与爱。来得快，去得也快。仿佛重生一般，你向这位守路者致意，然后让他回到自己的职责中去。>' WHERE `entry` = 41398 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '<宁静降临暮光林地。梦魇再一次被击退，但能维持多久，无人知晓。你心里明白，翡翠梦境之战尚未结束，然而想到那些坚定的守卫会继续这场正义之战，你便感到一丝慰藉。$B$B在你面前矗立着堪称自然最强之力的存在。青绿色的毛皮如星空般闪耀，他的双眼映出一片深蓝的智慧之海。你以为他力量的重压会把你压垮，可迎面而来的却是那熟悉的暖意——如清晨的阳光微风拂过挂满露珠的青草。$B$B你抬眼上望，视线与这位半神相接，一股力量之感奔涌全身。那是无可比拟的感受：成长、欣赏与爱。来得快，去得也快。仿佛重生一般，你向这位守路者致意，然后让他回到自己的职责中去。>');
