UPDATE `locales_quest` SET `OfferRewardText_loc4` = '你看到了吗？现在明白这份力量了吗？净化……一群蠢货……$B$B<玛塔乌斯不以为然地摇了摇头。>$B$B拿着它，从我眼前消失吧。' WHERE `entry` = 41416 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '你看到了吗？现在明白这份力量了吗？净化……一群蠢货……$B$B<玛塔乌斯不以为然地摇了摇头。>$B$B拿着它，从我眼前消失吧。');
