UPDATE `locales_quest` SET `OfferRewardText_loc4` = '看来你终究还算是个像样的$C。' WHERE `entry` = 41633 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '看来你终究还算是个像样的$C。');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '真是妙极了。干得漂亮。斯尔奥恩达该好好听着，以你为榜样。她天赋极高，可缺乏纪律这一点，既是我心头的大刺，也是她的。不过，我也只能怪她一半——毕竟我曾向她父母立誓，既要培育她的魔法天赋，也要助她成长为人。$B$B好旅人，我由衷感谢你。走之前，收下一件作为补偿。眼下时局多艰，务必步步留心。' WHERE `entry` = 41634 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '真是妙极了。干得漂亮。斯尔奥恩达该好好听着，以你为榜样。她天赋极高，可缺乏纪律这一点，既是我心头的大刺，也是她的。不过，我也只能怪她一半——毕竟我曾向她父母立誓，既要培育她的魔法天赋，也要助她成长为人。$B$B好旅人，我由衷感谢你。走之前，收下一件作为补偿。眼下时局多艰，务必步步留心。');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '办妥了？这就是他们那个杂种首领的首级？他们死得好，那帮家伙既已选了自己的路——一条通向灭亡的路。冒险者，我欣赏你的胆量。来，收下这份奖赏。有你这样的作为，我们或许很快就能重归安稳的日子。' WHERE `entry` = 41635 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '办妥了？这就是他们那个杂种首领的首级？他们死得好，那帮家伙既已选了自己的路——一条通向灭亡的路。冒险者，我欣赏你的胆量。来，收下这份奖赏。有你这样的作为，我们或许很快就能重归安稳的日子。');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '太好了，每次看到他们欢喜的神情，我自己也会笑出来。这些孩子是联盟的未来，而我们责任所在，就是尽力让他们为自己的人生抉择做好准备。我会确保教会知晓你今日的贡献——善行不会被忽视。你自己可有学到什么吗？巴罗岛在王国里是个争议不断的话题，许多迷信的人至今不敢提起它的名字。但无论如何，它都是我们过去的一部分，理应被记住。' WHERE `entry` = 41637 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '太好了，每次看到他们欢喜的神情，我自己也会笑出来。这些孩子是联盟的未来，而我们责任所在，就是尽力让他们为自己的人生抉择做好准备。我会确保教会知晓你今日的贡献——善行不会被忽视。你自己可有学到什么吗？巴罗岛在王国里是个争议不断的话题，许多迷信的人至今不敢提起它的名字。但无论如何，它都是我们过去的一部分，理应被记住。');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '<女巫以一种令人不适的方式咯咯笑着。>$B$B到底还是派上了用场。喏，我自酿的几瓶药水，专门给你的。你可以在这儿待一会儿，想问什么就问。这片林子知道的事，多数人是不敢问的……' WHERE `entry` = 41639 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '<女巫以一种令人不适的方式咯咯笑着。>$B$B到底还是派上了用场。喏，我自酿的几瓶药水，专门给你的。你可以在这儿待一会儿，想问什么就问。这片林子知道的事，多数人是不敢问的……');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '就是它！我真不知道该怎么谢你！要是把这些弄丢了，我怕自己根本承受不住。这里头全是我当巡山人时结识的好友留下的念想——每当公务把他们累垮，他们就会来山里看我、歇歇脚。为了他们，我们得尽快把这里夺回来。' WHERE `entry` = 41640 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '就是它！我真不知道该怎么谢你！要是把这些弄丢了，我怕自己根本承受不住。这里头全是我当巡山人时结识的好友留下的念想——每当公务把他们累垮，他们就会来山里看我、歇歇脚。为了他们，我们得尽快把这里夺回来。');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '<特工霍桑听完你的发现，长长地叹了口气。他显然疲惫不堪，开始揉眼睛，像是认了输。>$B$B这一整桩事到头来比我希望的还要难解。三名嫌犯的行为都与本案无关，我们又回到了原点。尽管沮丧，我还是得重新开始调查。我会撤销你的副手委任；你为我做的已经省下我宝贵的时间，我不能再多要求你什么。若我运气够好，军情七处会派人来支援我。在那之前，我必须专心办案了。再会，$N。' WHERE `entry` = 41646 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '<特工霍桑听完你的发现，长长地叹了口气。他显然疲惫不堪，开始揉眼睛，像是认了输。>$B$B这一整桩事到头来比我希望的还要难解。三名嫌犯的行为都与本案无关，我们又回到了原点。尽管沮丧，我还是得重新开始调查。我会撤销你的副手委任；你为我做的已经省下我宝贵的时间，我不能再多要求你什么。若我运气够好，军情七处会派人来支援我。在那之前，我必须专心办案了。再会，$N。');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '你是来领赏金的吧？$B$B<阿格娜什指挥官爽朗地大笑。>$B$B你今日的作为或许让裂刃的许多人保住了性命，为此我得谢你。你的行动无愧于部落，更无愧于这份奖赏。' WHERE `entry` = 41656 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '你是来领赏金的吧？$B$B<阿格娜什指挥官爽朗地大笑。>$B$B你今日的作为或许让裂刃的许多人保住了性命，为此我得谢你。你的行动无愧于部落，更无愧于这份奖赏。');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '<阿格娜什指挥官带着几分难以置信看着你。>$B$B你成功了？$B$B<阿格娜什指挥官爽朗地大笑起来。>$B$B你战胜了敌人，击败了科尔拉格！像他这样的强敌本是无畏的难题，可你偏偏站在这里，凯旋而归。今日你该为自己的荣耀而骄傲，因为你做到了极少有人能做到的事。$B$B收下这个，这是部落本身的谢意！' WHERE `entry` = 41658 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '<阿格娜什指挥官带着几分难以置信看着你。>$B$B你成功了？$B$B<阿格娜什指挥官爽朗地大笑起来。>$B$B你战胜了敌人，击败了科尔拉格！像他这样的强敌本是无畏的难题，可你偏偏站在这里，凯旋而归。今日你该为自己的荣耀而骄傲，因为你做到了极少有人能做到的事。$B$B收下这个，这是部落本身的谢意！');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '荣耀与光荣归于你的名字！你击败了我们的敌人，为部落带来了胜利。我备了几件东西，挑一件，让它陪你走完接下来的路。' WHERE `entry` = 41660 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '荣耀与光荣归于你的名字！你击败了我们的敌人，为部落带来了胜利。我备了几件东西，挑一件，让它陪你走完接下来的路。');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '我希望那位可怜的商人只是被抢了财物，而不是被打得流血——或者更糟。总之，你尽到了自己的本分，对此我不胜感激。我拿不出什么，就收下这幅画吧。那是我画的最后一幅。' WHERE `entry` = 41661 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '我希望那位可怜的商人只是被抢了财物，而不是被打得流血——或者更糟。总之，你尽到了自己的本分，对此我不胜感激。我拿不出什么，就收下这幅画吧。那是我画的最后一幅。');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '谢尔伍德公爵是我的挚友，他多次拒绝使用仆人。想到他会在你身上破例，我就觉得欣慰。我的武备库很简陋，眼下又是艰难时世——为你的辛劳，我最多只能以此相赠。' WHERE `entry` = 41665 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '谢尔伍德公爵是我的挚友，他多次拒绝使用仆人。想到他会在你身上破例，我就觉得欣慰。我的武备库很简陋，眼下又是艰难时世——为你的辛劳，我最多只能以此相赠。');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '啊，你来了！谢谢，谢谢你。要不是你及时赶到，他们怕是要把我的摊子给拆了。按约定——一包免费的琥珀釉甜甜圈，外加一枚小费。' WHERE `entry` = 41666 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '啊，你来了！谢谢，谢谢你。要不是你及时赶到，他们怕是要把我的摊子给拆了。按约定——一包免费的琥珀釉甜甜圈，外加一枚小费。');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '喂，$N，她还在盯着我看吗？唉，那女人让我浑身不自在。对了，马蹄铁拿到了吗？哦，感谢圣光。喏，拿着这个，动作快点。还有——以防万一，比赛期间别露面。' WHERE `entry` = 41667 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '喂，$N，她还在盯着我看吗？唉，那女人让我浑身不自在。对了，马蹄铁拿到了吗？哦，感谢圣光。喏，拿着这个，动作快点。还有——以防万一，比赛期间别露面。');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '都交给我吧，一切就绪。你帮了我，可以自己拿一个苹果。' WHERE `entry` = 41668 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '都交给我吧，一切就绪。你帮了我，可以自己拿一个苹果。');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '是奶奶派你来的？她还说了那些话？哦，我真想她。她寄来的东西我迫不及待要一一尝遍。听说北风的甜甜圈很有名气。而母亲给我的这个玩具，我会永远珍藏。谢谢你，冒险者。你帮了我一个大忙；作为暴风城的王子，我本该从军械库里挑样东西赏你——可我做不到。那就把我从大主教那里得来的这本书送给你吧。$B$B有空常来跟我讲讲你的冒险，这座宫殿又沉闷又无聊。我需要一个朋友。' WHERE `entry` = 41669 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '是奶奶派你来的？她还说了那些话？哦，我真想她。她寄来的东西我迫不及待要一一尝遍。听说北风的甜甜圈很有名气。而母亲给我的这个玩具，我会永远珍藏。谢谢你，冒险者。你帮了我一个大忙；作为暴风城的王子，我本该从军械库里挑样东西赏你——可我做不到。那就把我从大主教那里得来的这本书送给你吧。$B$B有空常来跟我讲讲你的冒险，这座宫殿又沉闷又无聊。我需要一个朋友。');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '随着它被送回，希望也回来了。今年的福音仪式上，我们要与那些信仰已经黯淡的人重新连结——在这片土地被混乱笼罩之时，他们正需要这个。' WHERE `entry` = 41671 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '随着它被送回，希望也回来了。今年的福音仪式上，我们要与那些信仰已经黯淡的人重新连结——在这片土地被混乱笼罩之时，他们正需要这个。');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '你杀了这么多？很好！它们的血会滋养土壤，长出的葡萄会带着胜利的甘甜。' WHERE `entry` = 41674 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '你杀了这么多？很好！它们的血会滋养土壤，长出的葡萄会带着胜利的甘甜。');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '没了首领，残存的兽人该滚回他们肮脏的故土了。' WHERE `entry` = 41676 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '没了首领，残存的兽人该滚回他们肮脏的故土了。');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '我在这儿都听见它们炸开了。干得好，挑一件吧。' WHERE `entry` = 41677 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '我在这儿都听见它们炸开了。干得好，挑一件吧。');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '很好，这是你的奖赏。若你偏离圣光之道，愿圣光惩罚你。' WHERE `entry` = 41678 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '很好，这是你的奖赏。若你偏离圣光之道，愿圣光惩罚你。');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '肉肉的带回了臭兽人。$B$B卫葛斯要把它搬回去给主人。$B$B臭臭把它弄丢了，就归肉肉的了。$B$B再见，肉肉的。' WHERE `entry` = 41681 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '肉肉的带回了臭兽人。$B$B卫葛斯要把它搬回去给主人。$B$B臭臭把它弄丢了，就归肉肉的了。$B$B再见，肉肉的。');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '那个袋子你留着吧，我已经用不着了。' WHERE `entry` = 41682 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '那个袋子你留着吧，我已经用不着了。');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '干得漂亮，这份奖励你当之无愧。' WHERE `entry` = 41683 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '干得漂亮，这份奖励你当之无愧。');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '所以霍桑把你雇为助手，帮他在北风查案。让我看看你查出了什么。$B$B<肖仔细翻过霍桑的日志，又把你在兽人营地找到的那封信读了更仔细的一遍。他神情严峻，把羊皮纸卷起，让你看末尾的印记。>$B$B这是风暴掠袭者氏族的印记。那是个古老的兽人氏族，我们本以为他们在二次大战末期就灭绝了。这封信我读完了，内容与王国的病症吻合：他们下令绑架疏于防范的平民，却不知为何把注意力转向了北风。不过，这还不是整桩事里最令人警觉的发现。先给你应得的奖励吧。' WHERE `entry` = 41685 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '所以霍桑把你雇为助手，帮他在北风查案。让我看看你查出了什么。$B$B<肖仔细翻过霍桑的日志，又把你在兽人营地找到的那封信读了更仔细的一遍。他神情严峻，把羊皮纸卷起，让你看末尾的印记。>$B$B这是风暴掠袭者氏族的印记。那是个古老的兽人氏族，我们本以为他们在二次大战末期就灭绝了。这封信我读完了，内容与王国的病症吻合：他们下令绑架疏于防范的平民，却不知为何把注意力转向了北风。不过，这还不是整桩事里最令人警觉的发现。先给你应得的奖励吧。');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '太好了，这是他们闯进我的地盘、洗劫比尔克庇护所、搅乱我采石计划的报应！他们活该！我得谢谢你。来，挑一件合意的——以你的本事，远远配得上。' WHERE `entry` = 41687 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '太好了，这是他们闯进我的地盘、洗劫比尔克庇护所、搅乱我采石计划的报应！他们活该！我得谢谢你。来，挑一件合意的——以你的本事，远远配得上。');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '<老太婆用药杵把草药捣碎，再拌入黏稠的琥珀树液。她搅匀药膏，涂到一条新绷带上。小心地取下旧绷带，又一批药膏敷在小鸭子的伤口上，疼得它好不委屈。女巫动作利落又轻柔地把绷带缠上它的左翼，固定妥当。>$B$B好了，宝贝；这能让它好得很快。像我们这位朋友这样毫无自保之力的小家伙，很少有幸遇到你这样的好心人。看它的样子，它同样记着你的付出。你的行为今日结下了一份了不起的羁绊。务必好好珍视——力量深深根植于这样的联系之中。' WHERE `entry` = 41691 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '<老太婆用药杵把草药捣碎，再拌入黏稠的琥珀树液。她搅匀药膏，涂到一条新绷带上。小心地取下旧绷带，又一批药膏敷在小鸭子的伤口上，疼得它好不委屈。女巫动作利落又轻柔地把绷带缠上它的左翼，固定妥当。>$B$B好了，宝贝；这能让它好得很快。像我们这位朋友这样毫无自保之力的小家伙，很少有幸遇到你这样的好心人。看它的样子，它同样记着你的付出。你的行为今日结下了一份了不起的羁绊。务必好好珍视——力量深深根植于这样的联系之中。');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '可惜了，我们今天失去的都是得力的密探。我会给他们的家人送信，他们为王国所做的贡献不会被遗忘。现在，说说这卷轴……' WHERE `entry` = 41694 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '可惜了，我们今天失去的都是得力的密探。我会给他们的家人送信，他们为王国所做的贡献不会被遗忘。现在，说说这卷轴……');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '任务完成。干得好，$C。遗憾的是，只要那些术士还在活动，我们恐怕终究没法彻底切断这里的恶魔势力。但能拿到多少小胜，我们就拿多少。记住，这是一场拼数量的战争，得把手上的东西用到极致！说到优势——你带回来的这块石碑里，肯定藏着恶魔插手此事的关键情报。我就知道！我会把它带给诺普西，他知道该怎么办。' WHERE `entry` = 41697 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '任务完成。干得好，$C。遗憾的是，只要那些术士还在活动，我们恐怕终究没法彻底切断这里的恶魔势力。但能拿到多少小胜，我们就拿多少。记住，这是一场拼数量的战争，得把手上的东西用到极致！说到优势——你带回来的这块石碑里，肯定藏着恶魔插手此事的关键情报。我就知道！我会把它带给诺普西，他知道该怎么办。');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '哦嚯嚯，好手艺啊，朋友。等我们按下这个起爆器，让那些爆炸的好东西在他们四周乱飞，那帮抱着恶魔大腿的兽人就有得瞧了！$B$B<鲁夫斯眼里满是狂喜，简直乐得像个胡子拉碴的孩子。>$B$B嚯，这让我想起有一回我差点把暴风城的矮人区给炸了。等我们为这该诅咒的岛屿操心完，我一边喝酒一边讲给你听。矮人一言为定！' WHERE `entry` = 41698 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '哦嚯嚯，好手艺啊，朋友。等我们按下这个起爆器，让那些爆炸的好东西在他们四周乱飞，那帮抱着恶魔大腿的兽人就有得瞧了！$B$B<鲁夫斯眼里满是狂喜，简直乐得像个胡子拉碴的孩子。>$B$B嚯，这让我想起有一回我差点把暴风城的矮人区给炸了。等我们为这该诅咒的岛屿操心完，我一边喝酒一边讲给你听。矮人一言为定！');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '我的罗盘！这么说维里克斯得到了他该得的下场？要我说，他死得好。我们哥布林有句话：一个哥布林的不幸，就是另一个哥布林的财运。罗盘回到我手里，剩下的就是把鸥翼号修到能用。谢谢你的帮忙，$C。维里克斯搜刮来的金币你可以留一些。要是你还想搭把手，我们绝不推辞。' WHERE `entry` = 41700 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '我的罗盘！这么说维里克斯得到了他该得的下场？要我说，他死得好。我们哥布林有句话：一个哥布林的不幸，就是另一个哥布林的财运。罗盘回到我手里，剩下的就是把鸥翼号修到能用。谢谢你的帮忙，$C。维里克斯搜刮来的金币你可以留一些。要是你还想搭把手，我们绝不推辞。');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '我得承认，我很佩服。我和其他人一直在赌你会带着几条肢体回来，还是我们得从海里把你的软身子捞上来。看来等我们回藏宝海湾，我得输给瑞克基几个金币了。不管怎么说，你的身手真是惊人。少了一个拖累，阿恩伊会松一口气。要是哪天你在外头冒险闯腻了，安德麦的热砂总部永远缺能打的狠角色。考虑一下，你准能融入进去！' WHERE `entry` = 41702 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '我得承认，我很佩服。我和其他人一直在赌你会带着几条肢体回来，还是我们得从海里把你的软身子捞上来。看来等我们回藏宝海湾，我得输给瑞克基几个金币了。不管怎么说，你的身手真是惊人。少了一个拖累，阿恩伊会松一口气。要是哪天你在外头冒险闯腻了，安德麦的热砂总部永远缺能打的狠角色。考虑一下，你准能融入进去！');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '真让我吃惊，整整一箱值钱的材料。光凭这些，就够重建鸥翼号的外框了。不得不说，我没想到你能办得这么漂亮。不过，愿意跑到这种穷乡僻壤小岛上来的人，本来就够疯的，是吧？总之，我们欠你一个大人情，朋友。哥布林一言为定！' WHERE `entry` = 41703 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '真让我吃惊，整整一箱值钱的材料。光凭这些，就够重建鸥翼号的外框了。不得不说，我没想到你能办得这么漂亮。不过，愿意跑到这种穷乡僻壤小岛上来的人，本来就够疯的，是吧？总之，我们欠你一个大人情，朋友。哥布林一言为定！');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '一股异常刺鼻的气味。要从它们身上提炼出可用的毒药得花些时间，但回报会十倍于所费。我得谢谢你——你的协助让这次任务的成功来得比你想的更快。' WHERE `entry` = 41708 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '一股异常刺鼻的气味。要从它们身上提炼出可用的毒药得花些时间，但回报会十倍于所费。我得谢谢你——你的协助让这次任务的成功来得比你想的更快。');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '你说纳迦？！这真是坏消息。若这些蜿蜒爬行的恶徒是这现象背后的黑手，那他们的真正意图我简直不敢去想。眼下我们挫败了他们的图谋。不过我在想：这颗珍珠是一直都在这里吗？若是，它一直就是破碎的吗？若不是，它为何被带到这里，又是谁带来的？纳迦还是鱼人？仍有太多疑问摆在我们面前，而且似乎没有一个容易解答。无论如何，我必须感谢你的协助。今日的发现让我对巴罗无尽的风暴有了更深的理解。等我一回到达文堡，就会把珍珠以及纳迦牵涉其中的事，呈报给博拉勒斯的潮汐议会。以他们近来对库尔提拉斯的不断侵袭来看，恐怕这不会是最后一次。$B$B请收下这个，作为你所作所为的一点微薄补偿。' WHERE `entry` = 41711 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '你说纳迦？！这真是坏消息。若这些蜿蜒爬行的恶徒是这现象背后的黑手，那他们的真正意图我简直不敢去想。眼下我们挫败了他们的图谋。不过我在想：这颗珍珠是一直都在这里吗？若是，它一直就是破碎的吗？若不是，它为何被带到这里，又是谁带来的？纳迦还是鱼人？仍有太多疑问摆在我们面前，而且似乎没有一个容易解答。无论如何，我必须感谢你的协助。今日的发现让我对巴罗无尽的风暴有了更深的理解。等我一回到达文堡，就会把珍珠以及纳迦牵涉其中的事，呈报给博拉勒斯的潮汐议会。以他们近来对库尔提拉斯的不断侵袭来看，恐怕这不会是最后一次。$B$B请收下这个，作为你所作所为的一点微薄补偿。');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '<格里塞尔达小心翼翼地读着那封积尘的信，生怕一个不留神就扯破纸页。一丝苦涩而温柔的神情掠过她的脸，她眼中微露惊讶，却不是得知坏消息的那种。取而代之，一抹笑意爬上了她的嘴角。>' WHERE `entry` = 41712 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '<格里塞尔达小心翼翼地读着那封积尘的信，生怕一个不留神就扯破纸页。一丝苦涩而温柔的神情掠过她的脸，她眼中微露惊讶，却不是得知坏消息的那种。取而代之，一抹笑意爬上了她的嘴角。>');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '$N，你还要再进通灵学院？为使用预言水晶球，你已经付出了不小的代价——或许你愿意再带一个上路。有了它，你便能再次面对大骨库里的凶险。$B$B尽管拿去。这你受之无愧。' WHERE `entry` = 41715 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '$N，你还要再进通灵学院？为使用预言水晶球，你已经付出了不小的代价——或许你愿意再带一个上路。有了它，你便能再次面对大骨库里的凶险。$B$B尽管拿去。这你受之无愧。');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '胜利之日终于到来，你的行动为部落占据这片土地铺平了道路。你的作为里处处可见萨尔的智慧。$B$B今日的功劳，自当有赏。' WHERE `entry` = 41721 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '胜利之日终于到来，你的行动为部落占据这片土地铺平了道路。你的作为里处处可见萨尔的智慧。$B$B今日的功劳，自当有赏。');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '我很满意。一想到有人为了力量背弃誓言、朋友与忠诚，我就从心底作呕。你为部落铲除了这样一个卑劣的叛徒。$B$B拿着这个，愿它助你的事业更进一步。' WHERE `entry` = 41724 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '我很满意。一想到有人为了力量背弃誓言、朋友与忠诚，我就从心底作呕。你为部落铲除了这样一个卑劣的叛徒。$B$B拿着这个，愿它助你的事业更进一步。');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '好精良的工艺，一看就知道这工程出自哥布林或侏儒之手。$B$B有了这些零件，我就能让裂刃哨所的进展再快一步。$B$B我得夸夸你。没有你找回来的这些构件与零件，这座营地还停留在石器时代呢。$B$B挑一件东西吧，但愿它们能派上用场。' WHERE `entry` = 41726 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '好精良的工艺，一看就知道这工程出自哥布林或侏儒之手。$B$B有了这些零件，我就能让裂刃哨所的进展再快一步。$B$B我得夸夸你。没有你找回来的这些构件与零件，这座营地还停留在石器时代呢。$B$B挑一件东西吧，但愿它们能派上用场。');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '乌索克宝石的力量正流淌在我的血脉里……这般力量令人狂喜！$B$B我重生了，这都多亏你替我做了所有的事。$B$B<先知莫萨发出一阵低沉而阴森的笑。>$B$B乌索克之坠饰的力量已被抽干，不过我相信你还是能派上点用场。$B$B<先知莫萨露出一个意味深长的笑容。>$B$B再会了，$C。' WHERE `entry` = 41731 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '乌索克宝石的力量正流淌在我的血脉里……这般力量令人狂喜！$B$B我重生了，这都多亏你替我做了所有的事。$B$B<先知莫萨发出一阵低沉而阴森的笑。>$B$B乌索克之坠饰的力量已被抽干，不过我相信你还是能派上点用场。$B$B<先知莫萨露出一个意味深长的笑容。>$B$B再会了，$C。');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '你不在的时候我做了些研究，也把这机械装置看了一遍。我想至少弄清了该怎么给它供能，但以它现在这副朽坏的样子，我没法保证一定能成。$B$B<塔尔韦格接过材料，开始为装置内的远古能量模块充能。随着一声轻响，机器缓缓转动起来——虽然慢得可怜，还带着老旧的滞涩。>$B$B啊哈！我成功了，多亏你把这件遗物带来给我研究、动手。愿它的力量助你一路顺遂。' WHERE `entry` = 41733 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '你不在的时候我做了些研究，也把这机械装置看了一遍。我想至少弄清了该怎么给它供能，但以它现在这副朽坏的样子，我没法保证一定能成。$B$B<塔尔韦格接过材料，开始为装置内的远古能量模块充能。随着一声轻响，机器缓缓转动起来——虽然慢得可怜，还带着老旧的滞涩。>$B$B啊哈！我成功了，多亏你把这件遗物带来给我研究、动手。愿它的力量助你一路顺遂。');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '我能感觉到——火焰中的腐化已经熄灭了。$B$B你在此地的付出意义重大，若没有你，我几乎束手无策。假以时日，这片土地会自我修复，元素也会归于安宁。我会留下来研究这场转变。$B$B为答谢你的作为，我送上一份配得上你辛劳的奖励。带着荣耀去吧，朋友。' WHERE `entry` = 41742 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '我能感觉到——火焰中的腐化已经熄灭了。$B$B你在此地的付出意义重大，若没有你，我几乎束手无策。假以时日，这片土地会自我修复，元素也会归于安宁。我会留下来研究这场转变。$B$B为答谢你的作为，我送上一份配得上你辛劳的奖励。带着荣耀去吧，朋友。');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '看吧，一股伟大的力量已赐予我们。我从没想过能亲眼见到女神本身的力量回应我的召唤。艾露恩之镰已然复原，它的力量而今交由你保管，用以抵御侵蚀我们世界的邪恶。$B$B$C，如此强大的力量也意味着沉重的责任。守护这件神器、向那些威胁我们使命之人施行艾露恩的意志，都托付给你了。' WHERE `entry` = 41745 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '看吧，一股伟大的力量已赐予我们。我从没想过能亲眼见到女神本身的力量回应我的召唤。艾露恩之镰已然复原，它的力量而今交由你保管，用以抵御侵蚀我们世界的邪恶。$B$B$C，如此强大的力量也意味着沉重的责任。守护这件神器、向那些威胁我们使命之人施行艾露恩的意志，都托付给你了。');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '你把残留物取回来了，干得好。老实说，派一个路过的旅人来替我们收拾烂摊子，我本有些不放心，但看来结果还不错。$B$B请代表我们这些人，收下这些药水，也许你路上用得上。' WHERE `entry` = 41746 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '你把残留物取回来了，干得好。老实说，派一个路过的旅人来替我们收拾烂摊子，我本有些不放心，但看来结果还不错。$B$B请代表我们这些人，收下这些药水，也许你路上用得上。');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '送卷轴来的？一定是扎尔迪玛派你来的。老实说，我很想念他在塔里的日子——他一直是个出色的学生。$B$B这些卷轴会派上大用场，我向你保证。请收下这个，就当是阿祖拉之塔的一点谢意。' WHERE `entry` = 41747 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '送卷轴来的？一定是扎尔迪玛派你来的。老实说，我很想念他在塔里的日子——他一直是个出色的学生。$B$B这些卷轴会派上大用场，我向你保证。请收下这个，就当是阿祖拉之塔的一点谢意。');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '今天失去了一位聪慧的心灵。也许在另一个世界，他真能成为艾泽拉斯的伟大法师之一。$B$B<塞欧克瑞图斯长长地叹了口气。>$B$B我想我再也找不到像他那样的人了，但我仍要谢谢你做了必须做的事。收下这个吧，这是我个人给你的谢意。' WHERE `entry` = 41748 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '今天失去了一位聪慧的心灵。也许在另一个世界，他真能成为艾泽拉斯的伟大法师之一。$B$B<塞欧克瑞图斯长长地叹了口气。>$B$B我想我再也找不到像他那样的人了，但我仍要谢谢你做了必须做的事。收下这个吧，这是我个人给你的谢意。');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '这才像话！有了这宝贝，卖给那些暗炉……哦，你还在啊。对！你的奖赏。喏，拿着这个，再添几个金币——你可真让本哥布林今天走了大运！' WHERE `entry` = 41749 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '这才像话！有了这宝贝，卖给那些暗炉……哦，你还在啊。对！你的奖赏。喏，拿着这个，再添几个金币——你可真让本哥布林今天走了大运！');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '<你还来不及反应，就把孤峰的头颅递给了格里姆比泰。带着不加掩饰的暴怒与憎恨，这豺狼人一把夺过头颅，狠狠咬了下去，将它撕咬得面目全非。做完这一切，他把残余扔进近旁的泥沼，任其沉入沼底。一声嗥叫从格里姆比泰的喉间迸出，其余豺狼人也随之应和。嚎叫声持续了片刻，回荡在整片湿地上空。>$B$B孤峰死了！藓皮真正自由了！你，藓皮的成员，永远！拿着这个，为了杀死叛徒。' WHERE `entry` = 41750 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '<你还来不及反应，就把孤峰的头颅递给了格里姆比泰。带着不加掩饰的暴怒与憎恨，这豺狼人一把夺过头颅，狠狠咬了下去，将它撕咬得面目全非。做完这一切，他把残余扔进近旁的泥沼，任其沉入沼底。一声嗥叫从格里姆比泰的喉间迸出，其余豺狼人也随之应和。嚎叫声持续了片刻，回荡在整片湿地上空。>$B$B孤峰死了！藓皮真正自由了！你，藓皮的成员，永远！拿着这个，为了杀死叛徒。');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '成了。生死是需要维系的循环，被污染的生命也该有重新绽放的机会。我心中的痛楚仍会持续，但至少我可以确信，斯伊瑞斯特尔阿斯兹不再受苦了。平安地去吧，凡人，愿你的旅途不再有悲剧。' WHERE `entry` = 41751 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '成了。生死是需要维系的循环，被污染的生命也该有重新绽放的机会。我心中的痛楚仍会持续，但至少我可以确信，斯伊瑞斯特尔阿斯兹不再受苦了。平安地去吧，凡人，愿你的旅途不再有悲剧。');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '你是个忠诚听话的仆从，$C。为你的效命，我备了一份奖赏。拿着它上路吧——黑暗女王不喜欢有人在她的地盘上无故逗留。' WHERE `entry` = 41753 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '你是个忠诚听话的仆从，$C。为你的效命，我备了一份奖赏。拿着它上路吧——黑暗女王不喜欢有人在她的地盘上无故逗留。');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '一块记载红印家族过往的石碑？！难以置信；快，让我看看！$B$B<托温调好镜片，目光扫过石碑的石面。随着他一行行辨认、读下去，他的脸越来越红、汗也越来越多，到最后手都明显抖了起来。>$B$B你——你……！这东西你从哪儿找来的？！你绝不许提，绝不许！这块该诅咒的石碑，谁都不能知道！绝对不行！来，拿着这个，你的嘴就给我闭紧，听明白了吗？！滚吧！' WHERE `entry` = 41755 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '一块记载红印家族过往的石碑？！难以置信；快，让我看看！$B$B<托温调好镜片，目光扫过石碑的石面。随着他一行行辨认、读下去，他的脸越来越红、汗也越来越多，到最后手都明显抖了起来。>$B$B你——你……！这东西你从哪儿找来的？！你绝不许提，绝不许！这块该诅咒的石碑，谁都不能知道！绝对不行！来，拿着这个，你的嘴就给我闭紧，听明白了吗？！滚吧！');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '死得好。卡兹莫丹残存的龙喉势力被我们狠狠打了一记。接下来就剩收拾残局，把还在我们地盘上乱窜的害虫清除干净。我向你致敬，$N。在我眼里，你就是真正的英雄。' WHERE `entry` = 41757 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '死得好。卡兹莫丹残存的龙喉势力被我们狠狠打了一记。接下来就剩收拾残局，把还在我们地盘上乱窜的害虫清除干净。我向你致敬，$N。在我眼里，你就是真正的英雄。');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '我在这生物的心脏深处感觉到了什么……它在渴望解脱，去对抗潜伏的黑暗。$B$B<凯姆·蛮鬃一脸困惑，轻轻叹了口气。>$B$B也许我最初的判断错了。唤醒这自然之物、令它陷入疯狂的，并非野猪人那种原始的黑暗魔法。不，是更黑暗、更阴邪的东西……我还有太多疑问需要进一步研究。无论我如何思量，你做得都很好。请收下这个，作为我的一点谢意。' WHERE `entry` = 41758 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '我在这生物的心脏深处感觉到了什么……它在渴望解脱，去对抗潜伏的黑暗。$B$B<凯姆·蛮鬃一脸困惑，轻轻叹了口气。>$B$B也许我最初的判断错了。唤醒这自然之物、令它陷入疯狂的，并非野猪人那种原始的黑暗魔法。不，是更黑暗、更阴邪的东西……我还有太多疑问需要进一步研究。无论我如何思量，你做得都很好。请收下这个，作为我的一点谢意。');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '如此诡异的魔法，那股盘踞在这些生物身上的气息我从未见过。$B$B这等能量绝非自然之物。我必须进一步研究才能查明真相。你干得好，$N。请收下这些金币，愿它们对你有用。' WHERE `entry` = 41759 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '如此诡异的魔法，那股盘踞在这些生物身上的气息我从未见过。$B$B这等能量绝非自然之物。我必须进一步研究才能查明真相。你干得好，$N。请收下这些金币，愿它们对你有用。');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '弗雷德里克，老朋友。你的魂魄残影还留在这件暗淡的小玩意里，早已不复昔日的荣光。总有一天，当我终于离世、离开这方天地时，我会再见到你……$B$B$N，愿祝福与你同在。这枚戒指会被我送去远离黑暗魔掌的湮灭之地，我保证。为你的英勇之举，请收下这件我仅存的贴身之物。你当之无愧。' WHERE `entry` = 41760 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '弗雷德里克，老朋友。你的魂魄残影还留在这件暗淡的小玩意里，早已不复昔日的荣光。总有一天，当我终于离世、离开这方天地时，我会再见到你……$B$B$N，愿祝福与你同在。这枚戒指会被我送去远离黑暗魔掌的湮灭之地，我保证。为你的英勇之举，请收下这件我仅存的贴身之物。你当之无愧。');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '我没看错人。作为外来的助力，你已证明自己是队里不可多得的人才。若哪天冒险的刺激在你心里淡了，军情七处永远欢迎你这样的人。$B$B请把调查结果报上来。时间不多了。' WHERE `entry` = 41761 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '我没看错人。作为外来的助力，你已证明自己是队里不可多得的人才。若哪天冒险的刺激在你心里淡了，军情七处永远欢迎你这样的人。$B$B请把调查结果报上来。时间不多了。');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '这么说，控制台被人动过手脚了？算不上意外，但终究是麻烦。虽然我不愿承认，可我们的技师得给它加双重保险，才能确保原本的功能恢复如初。总不能让这满满一池液体黄金连同我们一起炸上天吧！$B$B不管怎样，干得好。喏，收下这些，算是补偿你这番折腾——杜隆塔尔劳工联盟记你一份人情！' WHERE `entry` = 41764 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '这么说，控制台被人动过手脚了？算不上意外，但终究是麻烦。虽然我不愿承认，可我们的技师得给它加双重保险，才能确保原本的功能恢复如初。总不能让这满满一池液体黄金连同我们一起炸上天吧！$B$B不管怎样，干得好。喏，收下这些，算是补偿你这番折腾——杜隆塔尔劳工联盟记你一份人情！');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '你去过塔纳利斯，还帮了塞尔迪？太好了，那女人真是上天的恩赐！她头一次在耀水港趾高气扬地晃悠时，我的眼珠子差点掉出来。锈水财阀的高层官员，跑到我们这小地方来？！还要加入我们？！那感觉就像我在赌场最后一搏，把一辈子的积蓄翻了一倍。黑石岛的惨败之后，杜隆塔尔劳工联盟急需利润与士气的双重提振。要我说句不自夸的话，塔纳利斯那座钻井平台的主意太妙了。有滑芯管事，我就知道一定能成。$B$B尽管如此，风险投资公司不断的破坏与侵入仍让我不安。我怕他们的耐心快耗尽了——拉兹敦从来不是个顺不了心还能平静的人。$N，把耳朵眼睛都放尖一点。我们的未来不会轻松。' WHERE `entry` = 41767 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '你去过塔纳利斯，还帮了塞尔迪？太好了，那女人真是上天的恩赐！她头一次在耀水港趾高气扬地晃悠时，我的眼珠子差点掉出来。锈水财阀的高层官员，跑到我们这小地方来？！还要加入我们？！那感觉就像我在赌场最后一搏，把一辈子的积蓄翻了一倍。黑石岛的惨败之后，杜隆塔尔劳工联盟急需利润与士气的双重提振。要我说句不自夸的话，塔纳利斯那座钻井平台的主意太妙了。有滑芯管事，我就知道一定能成。$B$B尽管如此，风险投资公司不断的破坏与侵入仍让我不安。我怕他们的耐心快耗尽了——拉兹敦从来不是个顺不了心还能平静的人。$N，把耳朵眼睛都放尖一点。我们的未来不会轻松。');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '琥珀木领主如今连送王室文书都雇起低贱的农夫了？倒也不出所料，不过现在这些都无关紧要了。$B$B无论如何，你的差事办得还算妥当。不过我的谢意也是有限度的——我还有关键的情报要分析，所以请你行个方便，让我安安静静处理王国的疾患。' WHERE `entry` = 41768 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '琥珀木领主如今连送王室文书都雇起低贱的农夫了？倒也不出所料，不过现在这些都无关紧要了。$B$B无论如何，你的差事办得还算妥当。不过我的谢意也是有限度的——我还有关键的情报要分析，所以请你行个方便，让我安安静静处理王国的疾患。');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '<团结之基开始咔哒作响，齿轮转动起来。一阵异样的魔力嗡鸣传来，石面泛起蓝光。基座下方缓缓伸出一个托盘，上面放着一枚孤零零的钥匙。>' WHERE `entry` = 41774 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '<团结之基开始咔哒作响，齿轮转动起来。一阵异样的魔力嗡鸣传来，石面泛起蓝光。基座下方缓缓伸出一个托盘，上面放着一枚孤零零的钥匙。>');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '<博学者亚沃一手握水晶，一手捧魔典。他念出书页上的咒语，枢纽水晶开始动起来，被涌起的奥术能量激得震颤。震动越来越剧烈，在炫目的紫色火花中骤然破碎，留下两枚金色碎片在他手中。>$B$B成功了！太精彩了，真的！我很惊讶阿苏恩的法术竟近乎完美。稍加练习与改良，我们就能轻松、更安全地快速分解枢纽水晶了。$B$B$N，谢谢你的配合。这些碎片你留着，算作你协助的奖赏。请继续把你能找到的枢纽水晶带给我，好让我接着做实验。' WHERE `entry` = 41776 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '<博学者亚沃一手握水晶，一手捧魔典。他念出书页上的咒语，枢纽水晶开始动起来，被涌起的奥术能量激得震颤。震动越来越剧烈，在炫目的紫色火花中骤然破碎，留下两枚金色碎片在他手中。>$B$B成功了！太精彩了，真的！我很惊讶阿苏恩的法术竟近乎完美。稍加练习与改良，我们就能轻松、更安全地快速分解枢纽水晶了。$B$B$N，谢谢你的配合。这些碎片你留着，算作你协助的奖赏。请继续把你能找到的枢纽水晶带给我，好让我接着做实验。');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '<亚沃念咒之时，魔法碎片迸出噼啪作响的能量。热量自他掌中升腾，碎片化作液态彼此融合，微微悬在空中。片刻之后，一阵法力迸发——亚沃手中多了一枚枢纽水晶。>$B$B太棒了。亲眼看着它在我面前成形，这一幕我会永远记得。想想看，我们今日的成果竟有赖于一万年前的知识——我族珍视千年的智慧，正是我们韧性的明证。别发愁，年轻的$C，没有你的帮助，这一切都不可能。请留下这枚水晶作为奖赏。我坚信这工艺还能进一步改良，所以若你愿意再采集一次所需材料，我会很高兴。' WHERE `entry` = 41777 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '<亚沃念咒之时，魔法碎片迸出噼啪作响的能量。热量自他掌中升腾，碎片化作液态彼此融合，微微悬在空中。片刻之后，一阵法力迸发——亚沃手中多了一枚枢纽水晶。>$B$B太棒了。亲眼看着它在我面前成形，这一幕我会永远记得。想想看，我们今日的成果竟有赖于一万年前的知识——我族珍视千年的智慧，正是我们韧性的明证。别发愁，年轻的$C，没有你的帮助，这一切都不可能。请留下这枚水晶作为奖赏。我坚信这工艺还能进一步改良，所以若你愿意再采集一次所需材料，我会很高兴。');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '<把书搁到诺普西的桌上，这个侏儒惊叹于这些比例夸张的巨册。>$B$B如此精美，如此古老！要通读这些文献得花些时间。谢谢你，$N。你今天为王国做了一件大好事——保全了他们历史的一部分，哪怕它丑陋又令人沮丧。这些故事能教给我们宝贵的教训，所以对它们视而不见，长远来看只会害了你。记住，知识是你活下去的关键。' WHERE `entry` = 41783 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '<把书搁到诺普西的桌上，这个侏儒惊叹于这些比例夸张的巨册。>$B$B如此精美，如此古老！要通读这些文献得花些时间。谢谢你，$N。你今天为王国做了一件大好事——保全了他们历史的一部分，哪怕它丑陋又令人沮丧。这些故事能教给我们宝贵的教训，所以对它们视而不见，长远来看只会害了你。记住，知识是你活下去的关键。');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '这地方究竟发生了怎样的惨剧……？我一生从未见过如此恐怖之事，光是想到这等亵渎之物存在，就让我脊背发凉。$B$B$N，你敢深入这疯狂漩涡，是如今难得一见的英雄之举。你今日为王国、为整个联盟所做的贡献，在场者会铭记，受惠者会珍视。这些奖励配不上你功绩的分量，但还请你收下。$B$B你可以退下了。' WHERE `entry` = 41787 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '这地方究竟发生了怎样的惨剧……？我一生从未见过如此恐怖之事，光是想到这等亵渎之物存在，就让我脊背发凉。$B$B$N，你敢深入这疯狂漩涡，是如今难得一见的英雄之举。你今日为王国、为整个联盟所做的贡献，在场者会铭记，受惠者会珍视。这些奖励配不上你功绩的分量，但还请你收下。$B$B你可以退下了。');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '那么……办完了。必要的差事，完成得也算妥当。$B$B<他顿了顿，目光飘向被污染的月亮井，声音因不安而低沉。>$B$B然而……一道阴影仍盘踞在我心头。$B$B倘若乌索尔本人也堕落了呢？倘若这沉默并非出于轻蔑，而是疯狂……腐化？$B$B<他的语气转冷，透出一丝低抑的惊惶。>$B$B这是个危险的念头，我不敢轻率地放在心上。大德鲁伊必须知道此事。$B$B多谢你的……协助。愿风把你带离这被诅咒的地方。' WHERE `entry` = 41790 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '那么……办完了。必要的差事，完成得也算妥当。$B$B<他顿了顿，目光飘向被污染的月亮井，声音因不安而低沉。>$B$B然而……一道阴影仍盘踞在我心头。$B$B倘若乌索尔本人也堕落了呢？倘若这沉默并非出于轻蔑，而是疯狂……腐化？$B$B<他的语气转冷，透出一丝低抑的惊惶。>$B$B这是个危险的念头，我不敢轻率地放在心上。大德鲁伊必须知道此事。$B$B多谢你的……协助。愿风把你带离这被诅咒的地方。');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '嗯……凡人，你做了必须做的事。$B$B他们的心智终于静下来。再没有斯卡丁的低语，再没有扭曲魔法的锁链。只剩下寂静……和被剥夺已久的沉眠。$B$B不必为他们哀悼。他们的火焰如今点燃了我们的意志——他们最后的行为，会比他们曾有的疯狂燃烧得更亮。' WHERE `entry` = 41805 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '嗯……凡人，你做了必须做的事。$B$B他们的心智终于静下来。再没有斯卡丁的低语，再没有扭曲魔法的锁链。只剩下寂静……和被剥夺已久的沉眠。$B$B不必为他们哀悼。他们的火焰如今点燃了我们的意志——他们最后的行为，会比他们曾有的疯狂燃烧得更亮。');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '终于……那股污秽散去了。$B$B<随着黑暗魔法沉重的压迫消退，他的双翼微微舒展，空气本身仿佛都松了一口气。沼泽浑浊的水面泛起涟漪，像是从漫长的噩梦中醒来。>$B$B格里姆谷会痊愈的。大地记得如何愈合……只要给它时间。$B$B可这场胜利只是从野火上摘下一粒火星。斯卡丁并非独自行动——他们是逃离沉船的鼠辈。格瑞姆巴托吐出了更多同类，像腐斑一样散布在卡兹莫丹。$B$B而最糟的是……他们逃窜得井然有序。这不只是一次流放。他们在侍奉什么。某种古老的东西。某种饥渴的东西。$B$B记住我的话，凡人——这事没有结束。无论他们谋划什么……我们都必须在它找到我们之前先找到它。$B$B而下一次……我们带来的火，恐怕不够。' WHERE `entry` = 41809 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '终于……那股污秽散去了。$B$B<随着黑暗魔法沉重的压迫消退，他的双翼微微舒展，空气本身仿佛都松了一口气。沼泽浑浊的水面泛起涟漪，像是从漫长的噩梦中醒来。>$B$B格里姆谷会痊愈的。大地记得如何愈合……只要给它时间。$B$B可这场胜利只是从野火上摘下一粒火星。斯卡丁并非独自行动——他们是逃离沉船的鼠辈。格瑞姆巴托吐出了更多同类，像腐斑一样散布在卡兹莫丹。$B$B而最糟的是……他们逃窜得井然有序。这不只是一次流放。他们在侍奉什么。某种古老的东西。某种饥渴的东西。$B$B记住我的话，凡人——这事没有结束。无论他们谋划什么……我们都必须在它找到我们之前先找到它。$B$B而下一次……我们带来的火，恐怕不够。');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '成了。这枚翠绿符文与符文石一同系于世界之树的精魂之上。凝神体会它的力量吧，你的灵魂将在此地——诺达希尔脚下——重获新生。' WHERE `entry` = 41810 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '成了。这枚翠绿符文与符文石一同系于世界之树的精魂之上。凝神体会它的力量吧，你的灵魂将在此地——诺达希尔脚下——重获新生。');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '如此美丽——如此宏伟。我多希望能亲眼见到那棵古树，不过还是谢谢你费心将它寻回。我欠你一份人情。请代表我们德鲁伊，收下这份谢礼。' WHERE `entry` = 41812 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '如此美丽——如此宏伟。我多希望能亲眼见到那棵古树，不过还是谢谢你费心将它寻回。我欠你一份人情。请代表我们德鲁伊，收下这份谢礼。');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '麦格尼的胡子啊，整整一箱！还好这玩意儿不容易变质。来，你也拿点尝尝。' WHERE `entry` = 41813 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '麦格尼的胡子啊，整整一箱！还好这玩意儿不容易变质。来，你也拿点尝尝。');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '虽然保存得不好，它终究还是公爵的冠冕。这下能让探险者大厅那帮无赖闭嘴了！谢谢你，$R。这是我答应你的东西。' WHERE `entry` = 41814 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '虽然保存得不好，它终究还是公爵的冠冕。这下能让探险者大厅那帮无赖闭嘴了！谢谢你，$R。这是我答应你的东西。');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '我为你成为一名猎人而骄傲。挑一件我的东西带走吧，就当是你成功的纪念。' WHERE `entry` = 41818 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '我为你成为一名猎人而骄傲。挑一件我的东西带走吧，就当是你成功的纪念。');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '奥金走对了路——派你来而不是自己来，做得不错。一个酋长必须懂得做出恰当的选择。这是很有价值的情报，你辛苦了，该有奖励。也许有一天，我会请你协助处理这件事。我要回去履职，很快就会与大酋长商议。当心阴影，$N，尤其是它们肆意起舞的地方。' WHERE `entry` = 41820 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '奥金走对了路——派你来而不是自己来，做得不错。一个酋长必须懂得做出恰当的选择。这是很有价值的情报，你辛苦了，该有奖励。也许有一天，我会请你协助处理这件事。我要回去履职，很快就会与大酋长商议。当心阴影，$N，尤其是它们肆意起舞的地方。');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '对他们这种渣滓来说，这已是天大的仁慈。拿着吧，它们会带着安舍的光辉，陪你走过阴沉的荒野。' WHERE `entry` = 41822 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '对他们这种渣滓来说，这已是天大的仁慈。拿着吧，它们会带着安舍的光辉，陪你走过阴沉的荒野。');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '乌达佩把你派到我这儿来是对的。虽说我们不太愿意与部落打交道，但你的辛劳我记下了，报酬会照付。$B$B看在你话少又懂分寸的份上，我再加一份红包——乌达佩把你教得很好。' WHERE `entry` = 41825 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '乌达佩把你派到我这儿来是对的。虽说我们不太愿意与部落打交道，但你的辛劳我记下了，报酬会照付。$B$B看在你话少又懂分寸的份上，我再加一份红包——乌达佩把你教得很好。');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '骄傲地站直了，部落的子民。唯有血中奔涌着力量与雷霆之人，才能赢得光荣的胜利。' WHERE `entry` = 41828 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '骄傲地站直了，部落的子民。唯有血中奔涌着力量与雷霆之人，才能赢得光荣的胜利。');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '尽管我们未必是最后一次见到暗影议会的余烬，但这一场胜利意义非凡。我们对巴罗那片土地并无所求，它却给了我最好的礼物。$B$B基尔罗格起初满怀怨怼，嫉妒格罗玛什被当作英雄庆贺——而他自己却似被遗忘。可他嫉妒错了。我的兄长只是打下了地基。真正将建立未来的，是你、是我，也是基尔罗格。我很高兴他如今也这样看了。' WHERE `entry` = 41834 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '尽管我们未必是最后一次见到暗影议会的余烬，但这一场胜利意义非凡。我们对巴罗那片土地并无所求，它却给了我最好的礼物。$B$B基尔罗格起初满怀怨怼，嫉妒格罗玛什被当作英雄庆贺——而他自己却似被遗忘。可他嫉妒错了。我的兄长只是打下了地基。真正将建立未来的，是你、是我，也是基尔罗格。我很高兴他如今也这样看了。');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '两块碎片合在一起，就能当作进入城堡废墟的钥匙。当心，你要面对的是燃烧军团的爪牙，还有那些早已被遗忘的邪教信徒。' WHERE `entry` = 41837 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '两块碎片合在一起，就能当作进入城堡废墟的钥匙。当心，你要面对的是燃烧军团的爪牙，还有那些早已被遗忘的邪教信徒。');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '哦，比我铁炉堡的奶奶还灰头土脸。时间没善待这本古籍，潮湿的空气更是雪上加霜。我会把它妥善封进箱子，然后带回军情七处总部做分析。$N，我由衷感谢你。请挑一件与你的付出相称的奖赏。' WHERE `entry` = 41842 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '哦，比我铁炉堡的奶奶还灰头土脸。时间没善待这本古籍，潮湿的空气更是雪上加霜。我会把它妥善封进箱子，然后带回军情七处总部做分析。$N，我由衷感谢你。请挑一件与你的付出相称的奖赏。');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '哇，收获不小。也许不是我们该送的那批货，但我想海盗湾里那帮贪心的家伙不会太计较。太感谢你了，$N。我们欠你一个大人情。这件东西你拿去，它一直给我带来好运——我还能站在这儿就是证明。' WHERE `entry` = 41844 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '哇，收获不小。也许不是我们该送的那批货，但我想海盗湾里那帮贪心的家伙不会太计较。太感谢你了，$N。我们欠你一个大人情。这件东西你拿去，它一直给我带来好运——我还能站在这儿就是证明。');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '你找到了……以太阳之井起誓，我几乎不敢相信。$B$B<游侠菲亚琳娜举起水晶，斜对着光。阳光在它无瑕的切面上跳跃，折射出层层虹彩。>$B$B这……这绝不是普通宝石。这是一件杰作——是久已失传的手艺的明证。$B$B$C，我们由衷感谢你。我们这就行动——我和游侠们会赶赴现场，尽可能多地回收这种水晶……然后再向瑟伦领主复命。$B$B朋友，你今日为奎尔多雷立下了大功。愿星光永远指引你的道路。' WHERE `entry` = 41849 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '你找到了……以太阳之井起誓，我几乎不敢相信。$B$B<游侠菲亚琳娜举起水晶，斜对着光。阳光在它无瑕的切面上跳跃，折射出层层虹彩。>$B$B这……这绝不是普通宝石。这是一件杰作——是久已失传的手艺的明证。$B$B$C，我们由衷感谢你。我们这就行动——我和游侠们会赶赴现场，尽可能多地回收这种水晶……然后再向瑟伦领主复命。$B$B朋友，你今日为奎尔多雷立下了大功。愿星光永远指引你的道路。');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '<格罗尔丹盯着你带来的人头，朝地上啐了一口。>$B$B哈！这会给暗炉那些鼠辈一个再清楚不过的信号！消息传到他们那位所谓的领袖耳朵里只是时间问题。就当是个教训——惹铁炉堡的矮人之前，最好先掂量掂量，否则就得付出血的代价！' WHERE `entry` = 41853 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '<格罗尔丹盯着你带来的人头，朝地上啐了一口。>$B$B哈！这会给暗炉那些鼠辈一个再清楚不过的信号！消息传到他们那位所谓的领袖耳朵里只是时间问题。就当是个教训——惹铁炉堡的矮人之前，最好先掂量掂量，否则就得付出血的代价！');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '干得漂亮，$R！我这就让矿工们进场。用不了几天，我们就能重新开采，丹基塔斯也能再度恢复往日的荣光。$B$B请收下这个。它在我家传了好几代，但现在……是时候让它再次尝尝血的味道了。这是你应得的。' WHERE `entry` = 41856 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '干得漂亮，$R！我这就让矿工们进场。用不了几天，我们就能重新开采，丹基塔斯也能再度恢复往日的荣光。$B$B请收下这个。它在我家传了好几代，但现在……是时候让它再次尝尝血的味道了。这是你应得的。');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '屠夫的死讯传来，老实说，我很痛快。希望这是最后一次见到那些鱼人。现在我总算能专心于真正要紧的事——与龙喉的战争。我们还有更大的鱼要收拾。' WHERE `entry` = 41858 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '屠夫的死讯传来，老实说，我很痛快。希望这是最后一次见到那些鱼人。现在我总算能专心于真正要紧的事——与龙喉的战争。我们还有更大的鱼要收拾。');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '你让我们感到骄傲，小子。$B$B再次看到这面战旗……是啊，让人热血沸腾。兽人践踏了我们的城墙，却夺不走我们的精神。$B$B它重新飘扬在丹基塔斯上空，我们的人民就会记起自己是谁——以及我们为何而战。$B$B干得好。' WHERE `entry` = 41864 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '你让我们感到骄傲，小子。$B$B再次看到这面战旗……是啊，让人热血沸腾。兽人践踏了我们的城墙，却夺不走我们的精神。$B$B它重新飘扬在丹基塔斯上空，我们的人民就会记起自己是谁——以及我们为何而战。$B$B干得好。');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '<多尔萨斯眯眼看着样本，在手中来回翻动。他的表情阴沉下来。>$B$B正如我所担心的……这不是什么随机产生的腐化。这是暗影诅咒——正是当年莫德古德在格瑞姆巴托释放的那种灾厄。$B$B而且它至今仍在活动。这么多年过去，诅咒依然在渗出、蔓延，越过废墟。石头挡不住它，时间也没能削弱它。若无人出手……整片区域都会沦陷。这已远超我们独自应付的范畴。我会传信给达拉然的法师们，他们必须知道发生了什么。至于我们……眼下只能守望，并祈祷。' WHERE `entry` = 41868 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '<多尔萨斯眯眼看着样本，在手中来回翻动。他的表情阴沉下来。>$B$B正如我所担心的……这不是什么随机产生的腐化。这是暗影诅咒——正是当年莫德古德在格瑞姆巴托释放的那种灾厄。$B$B而且它至今仍在活动。这么多年过去，诅咒依然在渗出、蔓延，越过废墟。石头挡不住它，时间也没能削弱它。若无人出手……整片区域都会沦陷。这已远超我们独自应付的范畴。我会传信给达拉然的法师们，他们必须知道发生了什么。至于我们……眼下只能守望，并祈祷。');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '<哈尔菲格仔细听你讲述战斗经过。他饱经风霜的脸第一次松缓下来，嘴角浮起一丝疲惫的笑。>$B$B是啊……这正是我一直想听到的消息。你把他们打得够狠，是吧？我胸口都感觉到了——像是有副重担挪开了，哪怕只挪开一点。$B$B我再也没法抱住我的儿子……再也听不到他的笑声在厅堂里回荡……$B$B但多亏了你，别的父母也许还能。' WHERE `entry` = 41870 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '<哈尔菲格仔细听你讲述战斗经过。他饱经风霜的脸第一次松缓下来，嘴角浮起一丝疲惫的笑。>$B$B是啊……这正是我一直想听到的消息。你把他们打得够狠，是吧？我胸口都感觉到了——像是有副重担挪开了，哪怕只挪开一点。$B$B我再也没法抱住我的儿子……再也听不到他的笑声在厅堂里回荡……$B$B但多亏了你，别的父母也许还能。');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '水晶！$B$B<格鲁克森在手中翻看着它，显然十分满意。>$B$B和我设想的一模一样——完美无缺。这把锤子会因此变得非同凡响。$B$B那我得赶紧动手了。也许这一次……父亲终于会看到我的本事。' WHERE `entry` = 41879 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '水晶！$B$B<格鲁克森在手中翻看着它，显然十分满意。>$B$B和我设想的一模一样——完美无缺。这把锤子会因此变得非同凡响。$B$B那我得赶紧动手了。也许这一次……父亲终于会看到我的本事。');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '<地方法官胡尔达姆仔细听着，显然大为赞叹。>$B$B以熔炉与磐石起誓，你做到的远比我敢期望的更多！丹基塔斯与格里姆高地的居民欠你一份大人情。请收下这份奖励，作为我们的谢意。$B$B但也别就此松懈——山里还有龙喉的渣滓在游荡。我们矮人最清楚，山中的太平是万万轻信不得的。保持警觉，斧头别离手。' WHERE `entry` = 41882 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '<地方法官胡尔达姆仔细听着，显然大为赞叹。>$B$B以熔炉与磐石起誓，你做到的远比我敢期望的更多！丹基塔斯与格里姆高地的居民欠你一份大人情。请收下这份奖励，作为我们的谢意。$B$B但也别就此松懈——山里还有龙喉的渣滓在游荡。我们矮人最清楚，山中的太平是万万轻信不得的。保持警觉，斧头别离手。');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '<地方法官胡尔达姆带着几分难以置信看着你。>$B$B你成功了？以我的胡子起誓，我简直不敢相信！$B$B多亏你的辛劳，许多漫长而艰苦的战斗得以避免。丹基塔斯的矮人会永远记着你的恩情！请从这些东西里挑一件，就当是我们所有人的谢礼。' WHERE `entry` = 41884 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '<地方法官胡尔达姆带着几分难以置信看着你。>$B$B你成功了？以我的胡子起誓，我简直不敢相信！$B$B多亏你的辛劳，许多漫长而艰苦的战斗得以避免。丹基塔斯的矮人会永远记着你的恩情！请从这些东西里挑一件，就当是我们所有人的谢礼。');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '我必须提醒你，这配方要用得谨慎。材料一旦用错，做出来的东西会与翡翠猫鼬药剂截然相反。$B$B建议你严格照着配方来。' WHERE `entry` = 41887 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '我必须提醒你，这配方要用得谨慎。材料一旦用错，做出来的东西会与翡翠猫鼬药剂截然相反。$B$B建议你严格照着配方来。');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '你回来了——还带回了英雄勋章。你在那些险恶之地所做的努力并非无人知晓。每一场胜利，都让我们的立足之地更加稳固。$B$B联盟为你的英勇致谢。' WHERE `entry` = 41888 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '你回来了——还带回了英雄勋章。你在那些险恶之地所做的努力并非无人知晓。每一场胜利，都让我们的立足之地更加稳固。$B$B联盟为你的英勇致谢。');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '这些圣物已说明一切。伊恩辛迪斯不复存在，巫师领主的手也再难抬起。$B$B火焰之王会感受到这一击，并明白联盟随时准备再次熄灭他的烈焰——只要需要。收下这批补给，保持戒备。深处也许还潜伏着更多。' WHERE `entry` = 41889 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '这些圣物已说明一切。伊恩辛迪斯不复存在，巫师领主的手也再难抬起。$B$B火焰之王会感受到这一击，并明白联盟随时准备再次熄灭他的烈焰——只要需要。收下这批补给，保持戒备。深处也许还潜伏着更多。');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '这些徽章会传出清晰响亮的讯息：你再次证明了自己的力量。我们要借着这股势头继续推进。$B$B收下你的奖励，勇士。保持警觉，战争不会停歇——我们也不会。' WHERE `entry` = 41890 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '这些徽章会传出清晰响亮的讯息：你再次证明了自己的力量。我们要借着这股势头继续推进。$B$B收下你的奖励，勇士。保持警觉，战争不会停歇——我们也不会。');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '你带着胜利的徽章回来了。很好。这些足以让敌人明白：他们的黑暗挡不住我们的力量。你每挥出一击，都为部落开辟前路。$B$B你的忠诚不会被遗忘。' WHERE `entry` = 41891 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '你带着胜利的徽章回来了。很好。这些足以让敌人明白：他们的黑暗挡不住我们的力量。你每挥出一击，都为部落开辟前路。$B$B你的忠诚不会被遗忘。');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '这些圣物已说明一切。伊恩辛迪斯不复存在，巫师领主的手也再难抬起。$B$B火焰之王会感受到这一击，并明白部落随时准备再次熄灭他的烈焰——只要需要。收下这批补给，保持戒备。深处也许还潜伏着更多。' WHERE `entry` = 41892 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '这些圣物已说明一切。伊恩辛迪斯不复存在，巫师领主的手也再难抬起。$B$B火焰之王会感受到这一击，并明白部落随时准备再次熄灭他的烈焰——只要需要。收下这批补给，保持戒备。深处也许还潜伏着更多。');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '好浓烈的邪门法术！这正是我要找的东西。你干得好，也跑得够远。我送你一份阴影的庇护，善加使用，一路平安。' WHERE `entry` = 41896 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '好浓烈的邪门法术！这正是我要找的东西。你干得好，也跑得够远。我送你一份阴影的庇护，善加使用，一路平安。');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '干得漂亮。这些徽章证明你击穿了他们的防线，粉碎了他们的意志。我们要借这股势头深入他们的据点。$B$B收下这批补给，做好准备——也许很快又需要你。' WHERE `entry` = 41897 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '干得漂亮。这些徽章证明你击穿了他们的防线，粉碎了他们的意志。我们要借这股势头深入他们的据点。$B$B收下这批补给，做好准备——也许很快又需要你。');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '提出这样的请求让我难受……黑根部族曾是我们的朋友和最亲近的盟友。尽管看着熟悉的面孔、认出昔日的朋友令人心痛，但知道他们已从盘踞心中的邪恶中解脱，还是让我欣慰。你为木喉争了光，朋友，为此你应当得到奖赏。' WHERE `entry` = 41898 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '提出这样的请求让我难受……黑根部族曾是我们的朋友和最亲近的盟友。尽管看着熟悉的面孔、认出昔日的朋友令人心痛，但知道他们已从盘踞心中的邪恶中解脱，还是让我欣慰。你为木喉争了光，朋友，为此你应当得到奖赏。');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '看吧，这是我族人的造物——伟大的宁静灵契。它能以迅捷与优雅引导一个人的行动。木喉树液的精魂本身被注入了我们的力量，赋予了我们在这世上所拥有的恩赐。$B$B你为部族所做的努力，已为你赢得使用我们最传统灵契的权利。' WHERE `entry` = 41900 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '看吧，这是我族人的造物——伟大的宁静灵契。它能以迅捷与优雅引导一个人的行动。木喉树液的精魂本身被注入了我们的力量，赋予了我们在这世上所拥有的恩赐。$B$B你为部族所做的努力，已为你赢得使用我们最传统灵契的权利。');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '看吧，这是我族人的造物——伟大的共心灵契。它能增强人对自然世界的抵御，以便寻求指引。木喉树液的精魂本身被注入了我们的力量，赋予了我们在这世上所拥有的恩赐。$B$B你为部族所做的努力，已为你赢得使用我们最传统灵契的权利。' WHERE `entry` = 41901 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '看吧，这是我族人的造物——伟大的共心灵契。它能增强人对自然世界的抵御，以便寻求指引。木喉树液的精魂本身被注入了我们的力量，赋予了我们在这世上所拥有的恩赐。$B$B你为部族所做的努力，已为你赢得使用我们最传统灵契的权利。');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '看吧，这是我族人的造物——伟大的和谐灵契。它能强化并鼓舞自然本身的根须。木喉树液的精魂本身被注入了我们的力量，赋予了我们在这世上所拥有的恩赐。$B$B你为部族所做的努力，已为你赢得使用我们最传统灵契的权利。' WHERE `entry` = 41902 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '看吧，这是我族人的造物——伟大的和谐灵契。它能强化并鼓舞自然本身的根须。木喉树液的精魂本身被注入了我们的力量，赋予了我们在这世上所拥有的恩赐。$B$B你为部族所做的努力，已为你赢得使用我们最传统灵契的权利。');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '看吧，这是我族人的造物——伟大的亲缘灵契。它能让最破碎的灵魂重获生机，并提振士气。木喉树液的精魂本身被注入了我们的力量，赋予了我们在这世上所拥有的恩赐。$B$B你为部族所做的努力，已为你赢得使用我们最传统灵契的权利。' WHERE `entry` = 41903 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '看吧，这是我族人的造物——伟大的亲缘灵契。它能让最破碎的灵魂重获生机，并提振士气。木喉树液的精魂本身被注入了我们的力量，赋予了我们在这世上所拥有的恩赐。$B$B你为部族所做的努力，已为你赢得使用我们最传统灵契的权利。');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '看吧，这是我族人的造物——伟大的坚韧灵契。它能抵御深藏林中的腐化与剧毒。木喉树液的精魂本身被注入了我们的力量，赋予了我们在这世上所拥有的恩赐。$B$B你为部族所做的努力，已为你赢得使用我们最传统灵契的权利。' WHERE `entry` = 41904 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '看吧，这是我族人的造物——伟大的坚韧灵契。它能抵御深藏林中的腐化与剧毒。木喉树液的精魂本身被注入了我们的力量，赋予了我们在这世上所拥有的恩赐。$B$B你为部族所做的努力，已为你赢得使用我们最传统灵契的权利。');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '$N！你来了！一看到他们回到小屋，我就知道你成功了，可我还是为你的安危担心。我由衷感谢你。你不仅为无辜者冒了性命，还闯过了寻常冒险者根本不会遇上的凶险。$B$B请从这些东西里挑一件，作为你今日善举的见证。$N！' WHERE `entry` = 41906 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '$N！你来了！一看到他们回到小屋，我就知道你成功了，可我还是为你的安危担心。我由衷感谢你。你不仅为无辜者冒了性命，还闯过了寻常冒险者根本不会遇上的凶险。$B$B请从这些东西里挑一件，作为你今日善举的见证。$N！');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '啊，是的，这些小玩意完好地躲过了火焰。外来者，我得谢谢你做的一切。没有你，它们肯定已经被毁了。我只能奉上微薄的报酬，但愿这点心意足够表达我的谢意。' WHERE `entry` = 41907 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '啊，是的，这些小玩意完好地躲过了火焰。外来者，我得谢谢你做的一切。没有你，它们肯定已经被毁了。我只能奉上微薄的报酬，但愿这点心意足够表达我的谢意。');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '我感觉你周身带着一股肃穆之气。办妥了吗？我这桩过错终于被纠正了吗？$C，你为我族人立下了大功。你不仅把我们从不祥的结局中救了出来，还让我们看清：我们沿袭了数百年的路，莫罗盖人不应再走下去了。某种意义上，布乌罗比是对的——德莱尼人必须改变，才能为族人确保一个新的未来：一个不再充满恐惧、而是充满坚韧的未来。只可惜他曲解了自己信仰的本意。' WHERE `entry` = 41916 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '我感觉你周身带着一股肃穆之气。办妥了吗？我这桩过错终于被纠正了吗？$C，你为我族人立下了大功。你不仅把我们从不祥的结局中救了出来，还让我们看清：我们沿袭了数百年的路，莫罗盖人不应再走下去了。某种意义上，布乌罗比是对的——德莱尼人必须改变，才能为族人确保一个新的未来：一个不再充满恐惧、而是充满坚韧的未来。只可惜他曲解了自己信仰的本意。');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '布乌罗比也许被拦下了，但这场磨难远未结束。正如父亲所说，外面还有许多失落者已经迷失，而我们有责任把他们带回族群。这是件苦差事，我怕这不会是最后一个失去亲人的日子——但正因如此，我们必须竭尽所能阻止它发生。虽然我还经验不足、仍在受训，但我会尽可能支持父亲和长老们。$B$B我想了很久。虽然我在这里还有很多事要做，但你的作为在我心里点燃了一团前所未有过的火。这么多年来，我们把自己封闭在这片海岸，压抑自己，尽可能躲藏。可这并不是我想要的人生。但在确保村子安全之前，我不能离开。所以请收下这枚水晶。若你身陷险境，把它举向天空，我会在战斗中支援你。你可以信赖我，$N。' WHERE `entry` = 41917 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '布乌罗比也许被拦下了，但这场磨难远未结束。正如父亲所说，外面还有许多失落者已经迷失，而我们有责任把他们带回族群。这是件苦差事，我怕这不会是最后一个失去亲人的日子——但正因如此，我们必须竭尽所能阻止它发生。虽然我还经验不足、仍在受训，但我会尽可能支持父亲和长老们。$B$B我想了很久。虽然我在这里还有很多事要做，但你的作为在我心里点燃了一团前所未有过的火。这么多年来，我们把自己封闭在这片海岸，压抑自己，尽可能躲藏。可这并不是我想要的人生。但在确保村子安全之前，我不能离开。所以请收下这枚水晶。若你身陷险境，把它举向天空，我会在战斗中支援你。你可以信赖我，$N。');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '多可憎的造物。这进一步证明了我们这座圣殿中的生命正在一分一秒地腐烂。不过它仍有用途——它将为木喉铺平道路，去夺回被残暴恶徒撕走的一切。现在我能调配出足够强力的药膏，净化我们的神圣图腾了。$B$B$N，我们这小小集会向你致谢。凭你的勇气，我们朝净化木喉要塞迈出了第一步。收下这份精华，在你深入这魔物巢穴时使用。份量足够的话，你就能打破里面的结界，最终触及这一切的根源。' WHERE `entry` = 41933 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '多可憎的造物。这进一步证明了我们这座圣殿中的生命正在一分一秒地腐烂。不过它仍有用途——它将为木喉铺平道路，去夺回被残暴恶徒撕走的一切。现在我能调配出足够强力的药膏，净化我们的神圣图腾了。$B$B$N，我们这小小集会向你致谢。凭你的勇气，我们朝净化木喉要塞迈出了第一步。收下这份精华，在你深入这魔物巢穴时使用。份量足够的话，你就能打破里面的结界，最终触及这一切的根源。');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '在我们古老的教义里，有一则传说将所有熊怪部族联系在一起。它讲述了我族的诞生——据说在世界尚且年轻之时，双子神将我们带到了这个世上。那时他们还是幼崽，在卡利姆多未经触碰的荒野中嬉戏，在清晨沾满露水的草地上打滚。笑声弥漫在空气中，他们无拘无束的活力在四周飘荡。随着他们的力量满溢而出，湿草上的露珠落向巨树的根须，渗过树皮，与大地融为一体。日积月累，这些露珠逐渐生长，化作了那两位年轻熊神的模样。$B$B对我们熊怪来说，没有什么比协助始祖守护荒野更为重要。看着乌索尔第二次死去，让我的心充满痛苦与悲恸；像他这般高贵的存在，不该落得这样的下场。$N，木喉部族将永远欠你一份恩情。请收下这剂强效药膏，净化木喉要塞中残存的腐化。' WHERE `entry` = 41934 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '在我们古老的教义里，有一则传说将所有熊怪部族联系在一起。它讲述了我族的诞生——据说在世界尚且年轻之时，双子神将我们带到了这个世上。那时他们还是幼崽，在卡利姆多未经触碰的荒野中嬉戏，在清晨沾满露水的草地上打滚。笑声弥漫在空气中，他们无拘无束的活力在四周飘荡。随着他们的力量满溢而出，湿草上的露珠落向巨树的根须，渗过树皮，与大地融为一体。日积月累，这些露珠逐渐生长，化作了那两位年轻熊神的模样。$B$B对我们熊怪来说，没有什么比协助始祖守护荒野更为重要。看着乌索尔第二次死去，让我的心充满痛苦与悲恸；像他这般高贵的存在，不该落得这样的下场。$N，木喉部族将永远欠你一份恩情。请收下这剂强效药膏，净化木喉要塞中残存的腐化。');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '你说沃塔鲁斯？元素竟与凡人种族如此大规模地缔结盟约，令人担忧。尤其是在大地之环这里发生那些事之后。不过，这又引出了另一个问题：元素们究竟想从这样的联盟中得到什么？他们是黑风部族的仆从，还是反过来？若风之领主正把其他势力纳入麾下，那他们必定在为更大的图谋做准备。$B$B$N，谢谢你的勇气。你今日做到了了不起的事，也展现了作为我们教团萨满的潜力。其他人一定也期待你有更多出色表现。' WHERE `entry` = 41939 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '你说沃塔鲁斯？元素竟与凡人种族如此大规模地缔结盟约，令人担忧。尤其是在大地之环这里发生那些事之后。不过，这又引出了另一个问题：元素们究竟想从这样的联盟中得到什么？他们是黑风部族的仆从，还是反过来？若风之领主正把其他势力纳入麾下，那他们必定在为更大的图谋做准备。$B$B$N，谢谢你的勇气。你今日做到了了不起的事，也展现了作为我们教团萨满的潜力。其他人一定也期待你有更多出色表现。');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '这些骨头里已无生命，可孢子仍在不断寻找养分，像扭动的寄生虫搜寻猎物。这不是自然现象，却也不纯粹是魔法。到这一步，它已是一种全新的力量混合体，要根除它绝不容易。$B$B我们想出的办法，概念上很简单：把这株树苗种进你带来的富化土壤，然后给树施加孢子，观察会发生什么。此前我们用被瘟疫侵蚀的土壤种树苗时，它们几分钟内就枯萎，只留下一具变异的空壳。我们推测，元素富化的土壤能保护树免受侵扰，让它自由生长。这需要些时间，若你再来，说不定运气好能亲眼看到。$B$B无论如何，我得谢谢你，也谢谢贝瓦利。每一步都让我们更接近彻底治愈这片土地。' WHERE `entry` = 41942 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '这些骨头里已无生命，可孢子仍在不断寻找养分，像扭动的寄生虫搜寻猎物。这不是自然现象，却也不纯粹是魔法。到这一步，它已是一种全新的力量混合体，要根除它绝不容易。$B$B我们想出的办法，概念上很简单：把这株树苗种进你带来的富化土壤，然后给树施加孢子，观察会发生什么。此前我们用被瘟疫侵蚀的土壤种树苗时，它们几分钟内就枯萎，只留下一具变异的空壳。我们推测，元素富化的土壤能保护树免受侵扰，让它自由生长。这需要些时间，若你再来，说不定运气好能亲眼看到。$B$B无论如何，我得谢谢你，也谢谢贝瓦利。每一步都让我们更接近彻底治愈这片土地。');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '元素已经告诉我你回来了，$N。水要重新变得清澈还需要时间。但既然再没有腐化被灌入玛拉顿，自然便能从容地自我修复。$B$B这是你为艾泽拉斯重归平衡所做的贡献，收下吧。' WHERE `entry` = 41943 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '元素已经告诉我你回来了，$N。水要重新变得清澈还需要时间。但既然再没有腐化被灌入玛拉顿，自然便能从容地自我修复。$B$B这是你为艾泽拉斯重归平衡所做的贡献，收下吧。');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '肉！还这么多！帕拉什卡，是谁让你张罗这些的？还是你自己要做的？不管怎样，对我来说都一样。有了这些补给，我们的守卫就有力气再抵挡那些异端好些天！你的作为该有回报。喏，一份德莱尼传统食谱，按这新世界的口味改过。' WHERE `entry` = 41944 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '肉！还这么多！帕拉什卡，是谁让你张罗这些的？还是你自己要做的？不管怎样，对我来说都一样。有了这些补给，我们的守卫就有力气再抵挡那些异端好些天！你的作为该有回报。喏，一份德莱尼传统食谱，按这新世界的口味改过。');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '嗯，我很意外。你听进去了，还带来了上等的脑子。看那脑浆滴在地上的样子……$B$B<费娜·玛达尔看着你手中的灰白之物，直咽口水。她动作飞快，一把从你手里夺过去，大嚼起来。汁液、血水和碎屑落在地上。>$B$B这种鲜美的滋味我怎么都吃不够——滑腻的表面，黏稠的质地！简直妙极了！你补上了你的过失，小家伙。至少对自己行为的后果，你还算负责。总之，别再在这儿惹乱子了！' WHERE `entry` = 41945 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '嗯，我很意外。你听进去了，还带来了上等的脑子。看那脑浆滴在地上的样子……$B$B<费娜·玛达尔看着你手中的灰白之物，直咽口水。她动作飞快，一把从你手里夺过去，大嚼起来。汁液、血水和碎屑落在地上。>$B$B这种鲜美的滋味我怎么都吃不够——滑腻的表面，黏稠的质地！简直妙极了！你补上了你的过失，小家伙。至少对自己行为的后果，你还算负责。总之，别再在这儿惹乱子了！');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '好险。但愿这回能让他们长记性，不敢再来。你救了我的命和我这座宝贝农场，我感激不尽。你看，这片海岸的土壤性质特殊，作物很难生长；更何况即便待了这么久，你们世界的草木对我来说仍不易摸透。但我还是要为你的善举有所回报。拿去吧，都是自家种的！' WHERE `entry` = 41946 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '好险。但愿这回能让他们长记性，不敢再来。你救了我的命和我这座宝贝农场，我感激不尽。你看，这片海岸的土壤性质特殊，作物很难生长；更何况即便待了这么久，你们世界的草木对我来说仍不易摸透。但我还是要为你的善举有所回报。拿去吧，都是自家种的！');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '那么那个恶棍终于伏诛了？太好了。上一次它发狂时，足足有二十三名族人死在它爪下。少了它，我们总算能睡得安稳些了。' WHERE `entry` = 41947 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '那么那个恶棍终于伏诛了？太好了。上一次它发狂时，足足有二十三名族人死在它爪下。少了它，我们总算能睡得安稳些了。');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '那个长角的恶徒；你说这萨特叫塞勒娜？他吸收了晶簇的能量，注满自身，与德莱尼水晶融为了一体？！即便在这新世界，也还能见到这等亵渎之事。$C，德莱尼水晶的力量极具诱惑，一旦触及它脉动的能量，就需要极大的意志力才能不被吞没。有……些故事说，德莱尼人沉溺于水晶成瘾，最终自身晶化，自己也变成了德莱尼水晶。于是他们回到德拉诺，汇入它生命之血的循环。$B$B眼下我得为你带回的晶簇碎片准备净化仪式。这需要时间与心力，但我和莫罗盖人一样欠你太多。你对我族存续的持续支持，必将得到回报。请从这些手镯里挑一只，愿它能护你抵御将来临的邪恶。' WHERE `entry` = 41953 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '那个长角的恶徒；你说这萨特叫塞勒娜？他吸收了晶簇的能量，注满自身，与德莱尼水晶融为了一体？！即便在这新世界，也还能见到这等亵渎之事。$C，德莱尼水晶的力量极具诱惑，一旦触及它脉动的能量，就需要极大的意志力才能不被吞没。有……些故事说，德莱尼人沉溺于水晶成瘾，最终自身晶化，自己也变成了德莱尼水晶。于是他们回到德拉诺，汇入它生命之血的循环。$B$B眼下我得为你带回的晶簇碎片准备净化仪式。这需要时间与心力，但我和莫罗盖人一样欠你太多。你对我族存续的持续支持，必将得到回报。请从这些手镯里挑一只，愿它能护你抵御将来临的邪恶。');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '太妙了！最纯净的火焰——在这不起眼的火球之中，还跳动着一颗原初的心。世上任何邪恶，无论在此界还是他界，都躲不过它揭露一切的光。$B$B$N，时候到了。我们要将木喉要塞里的黑暗连根拔起。' WHERE `entry` = 41965 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '太妙了！最纯净的火焰——在这不起眼的火球之中，还跳动着一颗原初的心。世上任何邪恶，无论在此界还是他界，都躲不过它揭露一切的光。$B$B$N，时候到了。我们要将木喉要塞里的黑暗连根拔起。');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '<纳科格脸上掠过一丝撕裂般的神情。起初你分辨不出，但从他身上传来的哀鸣与抽泣证实了你的猜测：他在哭。>$B$B历经这么多年的苦难与折磨，我的族人终于能松一口气了。笼罩我们大多数同胞、甚至我们一位神圣神灵的腐化，终于被平息。这一切都要归功于像你这样勇敢守护者的奋战。我的话无法真正表达我们对你与你的同胞的感激。你将永远是木喉的座上宾，是熊怪珍视的英雄。' WHERE `entry` = 41966 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '<纳科格脸上掠过一丝撕裂般的神情。起初你分辨不出，但从他身上传来的哀鸣与抽泣证实了你的猜测：他在哭。>$B$B历经这么多年的苦难与折磨，我的族人终于能松一口气了。笼罩我们大多数同胞、甚至我们一位神圣神灵的腐化，终于被平息。这一切都要归功于像你这样勇敢守护者的奋战。我的话无法真正表达我们对你与你的同胞的感激。你将永远是木喉的座上宾，是熊怪珍视的英雄。');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '<布罗兰风角长长地舒了一口气。>$B$B知道能睡个安稳觉，你替我免去了多少煎熬。今日你为风角一族立了大功，作为感激，我送你一件信物，外来者。' WHERE `entry` = 41967 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '<布罗兰风角长长地舒了一口气。>$B$B知道能睡个安稳觉，你替我免去了多少煎熬。今日你为风角一族立了大功，作为感激，我送你一件信物，外来者。');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '<布尔罗克云蹄不紧不慢地检视着那些角，好奇地用指节敲着骨面。>$B$B我想这正是我要找的东西，你干得好。$B$B<这个傲慢的牛头人嘴角扬起一丝笑。>$B$B来，收下这个，就当是云蹄部族的一点谢意。' WHERE `entry` = 41968 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '<布尔罗克云蹄不紧不慢地检视着那些角，好奇地用指节敲着骨面。>$B$B我想这正是我要找的东西，你干得好。$B$B<这个傲慢的牛头人嘴角扬起一丝笑。>$B$B来，收下这个，就当是云蹄部族的一点谢意。');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '多么奇妙的材料，如此鲜亮，如此多彩！接下来的仪式会因它大放异彩，肯定比上一件法衣好得多。$B$B谢谢你，$C，请收下这份奖励。' WHERE `entry` = 41969 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '多么奇妙的材料，如此鲜亮，如此多彩！接下来的仪式会因它大放异彩，肯定比上一件法衣好得多。$B$B谢谢你，$C，请收下这份奖励。');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '<戈尔德娜克不紧不慢地端详着那片鳞，看它在光下熠熠生辉、散发魔力。>$B$B看来我要找的就是这东西。你干得好，来，收下这些金币，还有我给你的奖赏。' WHERE `entry` = 41974 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '<戈尔德娜克不紧不慢地端详着那片鳞，看它在光下熠熠生辉、散发魔力。>$B$B看来我要找的就是这东西。你干得好，来，收下这些金币，还有我给你的奖赏。');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '我整个少年时代都被这样的遗物环绕。风角的工艺确实精湛。$B$B没有你的帮助，这段历史就会被时间吞没。谢谢你，为今日你所做的一切。' WHERE `entry` = 41977 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '我整个少年时代都被这样的遗物环绕。风角的工艺确实精湛。$B$B没有你的帮助，这段历史就会被时间吞没。谢谢你，为今日你所做的一切。');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '血债血偿。你做得很好，用复仇回敬了这份邪恶。但愿你能体会我此刻的满足——即便怒火仍在我心中燃烧，我已得昭雪。$B$B谢谢你成为我怒火的执行者。请收下这些金币，是我，也是那些逝去之人的敬意。' WHERE `entry` = 41978 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '血债血偿。你做得很好，用复仇回敬了这份邪恶。但愿你能体会我此刻的满足——即便怒火仍在我心中燃烧，我已得昭雪。$B$B谢谢你成为我怒火的执行者。请收下这些金币，是我，也是那些逝去之人的敬意。');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '<凯恩以赞许的目光看着你。>$B$B你做得很好，为牛头人带来了安宁。死亡图腾再也不能作祟了，年轻的血液。请收下这件东西，愿它在你往后的日子里为你带来好运。' WHERE `entry` = 41982 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '<凯恩以赞许的目光看着你。>$B$B你做得很好，为牛头人带来了安宁。死亡图腾再也不能作祟了，年轻的血液。请收下这件东西，愿它在你往后的日子里为你带来好运。');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '这些真了不起。你确实有一手好厨艺——照这水平看，迪尔格可得当心，别太早被你抢了位置。总之，这是做好的锅具。带给迪尔格，告诉他随时可以回来，前提是他哥布林的自尊心答应。' WHERE `entry` = 41986 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '这些真了不起。你确实有一手好厨艺——照这水平看，迪尔格可得当心，别太早被你抢了位置。总之，这是做好的锅具。带给迪尔格，告诉他随时可以回来，前提是他哥布林的自尊心答应。');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '你拿到了！不过……它似乎已经受损。真可惜，但也许这样最好。这样一来，那些妄图在这世上散播纷争的人，就没法拿它作恶了。我会带着它回到大地之环，此刻它在我手上是安全的。再次谢谢你，$N。没有你的帮助，纳迦也许已经把它据为己有了。请收下这个，作为大地之环的赠礼。' WHERE `entry` = 41989 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '你拿到了！不过……它似乎已经受损。真可惜，但也许这样最好。这样一来，那些妄图在这世上散播纷争的人，就没法拿它作恶了。我会带着它回到大地之环，此刻它在我手上是安全的。再次谢谢你，$N。没有你的帮助，纳迦也许已经把它据为己有了。请收下这个，作为大地之环的赠礼。');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '办妥了吗？太好了，那我们别再在这儿浪费时间了。我去收好圣物，然后到莫罗盖村跟理查德会合。再次谢谢你帮忙，陌生人。我很感激。来，你可以自己留一件宝物，就当是我的谢意。' WHERE `entry` = 41990 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '办妥了吗？太好了，那我们别再在这儿浪费时间了。我去收好圣物，然后到莫罗盖村跟理查德会合。再次谢谢你帮忙，陌生人。我很感激。来，你可以自己留一件宝物，就当是我的谢意。');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '<克拉尔特吐出一口长气，如释重负，脸上的苍老愁容也松缓下来。>$B$B外来者，你替我卸下了重担，为此我得谢你。我的储备正为即将到来的冬眠一点点攒起来。$B$B请收下这个——让它证明，并非所有熊怪都沉溺于狂怒。' WHERE `entry` = 41991 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '<克拉尔特吐出一口长气，如释重负，脸上的苍老愁容也松缓下来。>$B$B外来者，你替我卸下了重担，为此我得谢你。我的储备正为即将到来的冬眠一点点攒起来。$B$B请收下这个——让它证明，并非所有熊怪都沉溺于狂怒。');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '骄傲与憎恨蒙蔽了他们，使他们走上狡黠而诡秘的道路。他们选择拥抱年轻的洛修的阴暗面——当整个世界都与你为敌时，那个忤逆的兄弟确实颇具吸引力。$B$B潮流正在转变。暖意让我的毛发微微发颤。安舍又与我们同在了。' WHERE `entry` = 41993 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '骄傲与憎恨蒙蔽了他们，使他们走上狡黠而诡秘的道路。他们选择拥抱年轻的洛修的阴暗面——当整个世界都与你为敌时，那个忤逆的兄弟确实颇具吸引力。$B$B潮流正在转变。暖意让我的毛发微微发颤。安舍又与我们同在了。');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '那就这样吧。今天是沉重的一天，但已无所谓。黎明到来时，安舍的温暖会拥抱我。' WHERE `entry` = 41994 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '那就这样吧。今天是沉重的一天，但已无所谓。黎明到来时，安舍的温暖会拥抱我。');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '这么说你确实削减了它们的数量。嗯，聊胜于无。真到了忍无可忍的时候，我就往耳朵里塞点丝绸。' WHERE `entry` = 41996 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '这么说你确实削减了它们的数量。嗯，聊胜于无。真到了忍无可忍的时候，我就往耳朵里塞点丝绸。');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '虽然眼下还没法给你做新衣服，但你可以在这些里挑一件——都是用我手上最后一批材料赶制的。' WHERE `entry` = 41999 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '虽然眼下还没法给你做新衣服，但你可以在这些里挑一件——都是用我手上最后一批材料赶制的。');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '我感觉到南方传来了一丝安宁，你的任务确实成功了。' WHERE `entry` = 42000 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '我感觉到南方传来了一丝安宁，你的任务确实成功了。');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '以造物主之名，他说对了。哦，奥杜姆，你这个疯子！拿命去赌这东西根本不值得！$B$B<布罗哈恩长长地吐出一口气，疲惫不堪。>$B$B$N，我这位朋友一直在寻找一件他认为是泰坦遗物的古物——泰坦，那些曾造访艾泽拉斯的天界存在。我们伟大的铁炉堡里，许多学者与教授都推测矮人的诞生与那些神祇之间有关联。他以为你手上这件东西能让矮人更接近真相，可惜它似乎并不完整。匀矛是用性命换来这惊人发现的，我会带着骄傲与敬意对待他的牺牲。等我在暴风城的事了结，我会把它呈交给大图书馆的资深探险家麦格拉斯做进一步研究。$B$B至于你，无论出于你的英勇还是对考古的贡献，都该有一份公正的奖赏。旅人，愿你一路顺遂。' WHERE `entry` = 42007 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '以造物主之名，他说对了。哦，奥杜姆，你这个疯子！拿命去赌这东西根本不值得！$B$B<布罗哈恩长长地吐出一口气，疲惫不堪。>$B$B$N，我这位朋友一直在寻找一件他认为是泰坦遗物的古物——泰坦，那些曾造访艾泽拉斯的天界存在。我们伟大的铁炉堡里，许多学者与教授都推测矮人的诞生与那些神祇之间有关联。他以为你手上这件东西能让矮人更接近真相，可惜它似乎并不完整。匀矛是用性命换来这惊人发现的，我会带着骄傲与敬意对待他的牺牲。等我在暴风城的事了结，我会把它呈交给大图书馆的资深探险家麦格拉斯做进一步研究。$B$B至于你，无论出于你的英勇还是对考古的贡献，都该有一份公正的奖赏。旅人，愿你一路顺遂。');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '传闻一点不假，我很少见到如此柔滑细密的皮毛。我已经等不及要动手处理它了。按约定，也有你一份奖励。我相信你会派上大用场。' WHERE `entry` = 42008 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '传闻一点不假，我很少见到如此柔滑细密的皮毛。我已经等不及要动手处理它了。按约定，也有你一份奖励。我相信你会派上大用场。');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '你的朋友胆子不小，也许还有点迟钝。不过礼物就是礼物，下次他再来，我照样欢迎。你从小龙身上取下的那块水晶叫星辰碎片，是陨石的碎屑。瞧，谜团解开了。那么，除非你还有德莱尼水晶要给我，我就回去忙我的事了。' WHERE `entry` = 42012 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '你的朋友胆子不小，也许还有点迟钝。不过礼物就是礼物，下次他再来，我照样欢迎。你从小龙身上取下的那块水晶叫星辰碎片，是陨石的碎屑。瞧，谜团解开了。那么，除非你还有德莱尼水晶要给我，我就回去忙我的事了。');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '很好，洛修的影响正在消退，干得漂亮。就当是允许风角一族在我的村子外多待一阵子了。' WHERE `entry` = 42014 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '很好，洛修的影响正在消退，干得漂亮。就当是允许风角一族在我的村子外多待一阵子了。');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '自然自有其规律，她的身体会像所有躯体一样归于尘土。我祈求洛修保全她的心智，让她在她曾深爱的群星间漫游。' WHERE `entry` = 42015 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '自然自有其规律，她的身体会像所有躯体一样归于尘土。我祈求洛修保全她的心智，让她在她曾深爱的群星间漫游。');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '阿什托泰姆送来一份滑稽的礼物。他本是要去与月蹄一族商谈邦交与盟约的，却被挡在门外，于是决定把月蹄长老最老的朋友的心脏当作礼物送我——那个人如今已被他自己视作敌人。真是乱象丛生。' WHERE `entry` = 42018 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '阿什托泰姆送来一份滑稽的礼物。他本是要去与月蹄一族商谈邦交与盟约的，却被挡在门外，于是决定把月蹄长老最老的朋友的心脏当作礼物送我——那个人如今已被他自己视作敌人。真是乱象丛生。');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '你居然真找到了一头。很好。交给我，然后等着。' WHERE `entry` = 42019 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '你居然真找到了一头。很好。交给我，然后等着。');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '成了。它虽不如原版那般强大，但这份精华足以浇熄那些在圣洞里散布枯颚腐化的火盆。若还需要更多，你知道上哪儿找我，勇敢的冒险者。' WHERE `entry` = 42021 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '成了。它虽不如原版那般强大，但这份精华足以浇熄那些在圣洞里散布枯颚腐化的火盆。若还需要更多，你知道上哪儿找我，勇敢的冒险者。');
UPDATE `locales_quest` SET `OfferRewardText_loc4` = '拿好了，朋友。你能感觉到其中奔涌的灵力吗？未经磨练的人会在它的威势下发抖。所以请务必善用它，去对付黑暗的敌人。' WHERE `entry` = 42023 AND (`OfferRewardText_loc4` IS NULL OR `OfferRewardText_loc4` <> '拿好了，朋友。你能感觉到其中奔涌的灵力吗？未经磨练的人会在它的威势下发抖。所以请务必善用它，去对付黑暗的敌人。');
